#!/usr/bin/env python3
"""HTML to Markdown converter - reimplement of html-to-markdown CLI tool."""

import sys
import os
import re
import glob
import argparse
from html.parser import HTMLParser
import urllib.parse


# ============================================================
# DOM Tree
# ============================================================

class Node:
    """Represents a DOM node."""
    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag  # element tag or '#text' for text nodes
        self.attrs = attrs or {}  # dict of attributes
        self.children = []
        self.parent = parent
        self.text_content = ''  # only for #text nodes

    def append_child(self, child):
        child.parent = self
        self.children.append(child)

    def get_attr(self, name, default=''):
        return self.attrs.get(name, default)

    def has_class(self, cls):
        classes = self.attrs.get('class', '').split()
        return cls in classes

    def get_classes(self):
        return self.attrs.get('class', '').split()

    def text_content_of(self):
        """Get all text content of this node."""
        if self.tag == '#text':
            return self.text_content
        return ''.join(c.text_content_of() for c in self.children)

    def find_all(self, tag):
        """Find all descendant nodes with the given tag."""
        results = []
        for child in self.children:
            if child.tag == tag:
                results.append(child)
            results.extend(child.find_all(tag))
        return results

    def __repr__(self):
        if self.tag == '#text':
            return f'Text({repr(self.text_content)})'
        return f'<{self.tag} {self.attrs}>'


# ============================================================
# HTML Parser
# ============================================================

VOID_ELEMENTS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
}

SKIP_CONTENT_ELEMENTS = {'script', 'style', 'head'}


class HTMLDOMParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node('root')
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {}
        for k, v in attrs:
            attrs_dict[k.lower()] = v or ''
        node = Node(tag, attrs_dict)
        self.stack[-1].append_child(node)
        if tag not in VOID_ELEMENTS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in VOID_ELEMENTS:
            return
        # Find matching open tag
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        # Skip content of certain elements
        for node in self.stack:
            if node.tag in SKIP_CONTENT_ELEMENTS:
                return
        node = Node('#text')
        node.text_content = data
        self.stack[-1].append_child(node)


def parse_html(html_str):
    """Parse HTML string and return root DOM node."""
    parser = HTMLDOMParser()
    parser.feed(html_str)
    return parser.root


# ============================================================
# CSS Selector Engine
# ============================================================

def parse_selector(selector_str):
    """Parse a CSS selector string into a list of selector groups (comma-separated)."""
    # Split by comma, but not inside brackets
    groups = []
    depth = 0
    current = ''
    for c in selector_str:
        if c == '[':
            depth += 1
            current += c
        elif c == ']':
            depth -= 1
            current += c
        elif c == ',' and depth == 0:
            groups.append(current.strip())
            current = ''
        else:
            current += c
    if current.strip():
        groups.append(current.strip())
    return groups


def parse_simple_selector(s):
    """Parse a simple selector (no combinators) into a dict."""
    # Returns dict with: tag, id, classes, attrs
    result = {'tag': None, 'id': None, 'classes': [], 'attrs': []}

    i = 0
    # Tag
    if i < len(s) and s[i] not in '.#[:*':
        j = i
        while j < len(s) and s[j] not in '.#[:':
            j += 1
        result['tag'] = s[i:j].lower() if s[i:j] else None
        i = j
    elif i < len(s) and s[i] == '*':
        i += 1  # universal selector

    # Classes, IDs, attrs
    while i < len(s):
        if s[i] == '.':
            i += 1
            j = i
            while j < len(s) and s[j] not in '.#[:':
                j += 1
            result['classes'].append(s[i:j])
            i = j
        elif s[i] == '#':
            i += 1
            j = i
            while j < len(s) and s[j] not in '.#[:':
                j += 1
            result['id'] = s[i:j]
            i = j
        elif s[i] == '[':
            i += 1
            j = s.index(']', i)
            attr_str = s[i:j]
            i = j + 1
            # Parse attribute selector
            if '*=' in attr_str:
                k, v = attr_str.split('*=', 1)
                result['attrs'].append(('*=', k.strip(), v.strip("'\"")))
            elif '~=' in attr_str:
                k, v = attr_str.split('~=', 1)
                result['attrs'].append(('~=', k.strip(), v.strip("'\"")))
            elif '^=' in attr_str:
                k, v = attr_str.split('^=', 1)
                result['attrs'].append(('^=', k.strip(), v.strip("'\"")))
            elif '$=' in attr_str:
                k, v = attr_str.split('$=', 1)
                result['attrs'].append(('$=', k.strip(), v.strip("'\"")))
            elif '=' in attr_str:
                k, v = attr_str.split('=', 1)
                result['attrs'].append(('=', k.strip(), v.strip("'\"")))
            else:
                result['attrs'].append(('exist', attr_str.strip(), ''))
        elif s[i] == ':':
            # Skip pseudo-selectors
            i += 1
            while i < len(s) and s[i] not in '.#[:':
                i += 1
        else:
            i += 1

    return result


def match_simple_selector(node, sel):
    """Check if node matches a simple selector dict."""
    if node.tag == '#text':
        return False
    if sel['tag'] and node.tag != sel['tag']:
        return False
    if sel['id'] and node.attrs.get('id', '') != sel['id']:
        return False
    node_classes = node.get_classes()
    for cls in sel['classes']:
        if cls not in node_classes:
            return False
    for op, attr, val in sel['attrs']:
        node_val = node.attrs.get(attr, None)
        if op == 'exist':
            if node_val is None:
                return False
        elif node_val is None:
            return False
        elif op == '=':
            if node_val != val:
                return False
        elif op == '*=':
            if val not in node_val:
                return False
        elif op == '^=':
            if not node_val.startswith(val):
                return False
        elif op == '$=':
            if not node_val.endswith(val):
                return False
        elif op == '~=':
            if val not in node_val.split():
                return False
    return True


def parse_selector_chain(selector_str):
    """Parse a selector into a chain of (combinator, simple_selector) pairs."""
    # Returns list of (combinator, simple_selector_dict)
    # combinator: ' ' (descendant), '>' (child), '+' (adjacent), '~' (sibling)
    tokens = []
    i = 0
    s = selector_str.strip()

    while i < len(s):
        # Skip whitespace (could be descendant combinator)
        if s[i] == ' ':
            i += 1
            while i < len(s) and s[i] == ' ':
                i += 1
            if i < len(s) and s[i] not in '>+~':
                tokens.append((' ', None))
        elif s[i] in '>+~':
            combinator = s[i]
            i += 1
            while i < len(s) and s[i] == ' ':
                i += 1
            tokens.append((combinator, None))
        else:
            # Parse simple selector
            j = i
            depth = 0
            while j < len(s):
                if s[j] == '[':
                    depth += 1
                elif s[j] == ']':
                    depth -= 1
                elif depth == 0 and (s[j] == ' ' or s[j] in '>+~'):
                    break
                j += 1
            simple = parse_simple_selector(s[i:j])
            if tokens and tokens[-1][1] is None:
                tokens[-1] = (tokens[-1][0], simple)
            else:
                tokens.append((None, simple))
            i = j

    return tokens


def match_selector_chain(node, chain):
    """Check if node matches a selector chain."""
    if not chain:
        return False

    last_comb, last_sel = chain[-1]

    if not match_simple_selector(node, last_sel):
        return False

    if len(chain) == 1:
        return True

    rest = chain[:-1]

    # Get the combinator before this selector
    # The combinator is in the rest chain's last entry (if it's just combinator) 
    # or the current node's last combinator
    # Actually, the combinator applies between rest[-1] and last

    # Find the combinator
    if rest and rest[-1][1] is None:
        combinator = rest[-1][0]
        rest = rest[:-1]
    else:
        combinator = ' '  # default descendant

    if combinator == '>':
        # Parent must match
        if node.parent:
            return match_selector_chain(node.parent, rest)
        return False
    elif combinator == ' ':
        # Any ancestor must match
        ancestor = node.parent
        while ancestor:
            if match_selector_chain(ancestor, rest):
                return True
            ancestor = ancestor.parent
        return False
    elif combinator == '+':
        # Previous sibling must match
        if node.parent:
            siblings = node.parent.children
            idx = siblings.index(node)
            if idx > 0:
                prev = siblings[idx - 1]
                return match_selector_chain(prev, rest)
        return False
    elif combinator == '~':
        # Any previous sibling must match
        if node.parent:
            siblings = node.parent.children
            idx = siblings.index(node)
            for i in range(idx):
                if match_selector_chain(siblings[i], rest):
                    return True
        return False

    return False


def matches_selector(node, selector_str):
    """Check if node matches a CSS selector string."""
    groups = parse_selector(selector_str)
    for group in groups:
        chain = parse_selector_chain(group.strip())
        if chain and match_selector_chain(node, chain):
            return True
    return False


def filter_nodes(root, include_selectors=None, exclude_selectors=None):
    """Apply include/exclude selectors to the DOM tree."""
    if include_selectors:
        # Find all nodes matching include selectors
        matched = []

        def find_matching(node):
            for sel in include_selectors:
                if matches_selector(node, sel):
                    matched.append(node)
                    return
            for child in node.children:
                if child.tag != '#text':
                    find_matching(child)

        find_matching(root)

        # Create a new root with only matched subtrees
        new_root = Node('root')
        for node in matched:
            new_root.append_child(node)
        return new_root

    if exclude_selectors:
        # Mark nodes to exclude
        excluded = set()

        def find_excluded(node):
            for sel in exclude_selectors:
                if matches_selector(node, sel):
                    excluded.add(id(node))
                    return
            for child in node.children[:]:
                if child.tag != '#text':
                    find_excluded(child)

        find_excluded(root)

        # Remove excluded nodes
        def remove_excluded(node):
            node.children = [c for c in node.children if id(c) not in excluded]
            for child in node.children:
                remove_excluded(child)

        remove_excluded(root)

    return root


# ============================================================
# URL Handling
# ============================================================

def encode_url(url):
    """Encode special characters in URL for markdown."""
    if not url:
        return url
    # Encode characters that would break markdown link syntax
    # Parentheses and brackets need encoding
    url = url.replace('(', '%28').replace(')', '%29')
    url = url.replace('[', '%5B').replace(']', '%5D')
    # Spaces
    url = url.replace(' ', '%20')
    # Backslash
    url = url.replace('\\', '%5C')
    return url


def resolve_url(url, domain):
    """Resolve relative URL against domain."""
    if not url or not domain:
        return url
    # If already absolute, return as-is
    if url.startswith('http://') or url.startswith('https://') or url.startswith('//'):
        return url
    if url.startswith('mailto:') or url.startswith('tel:'):
        return url
    # Resolve relative
    base = domain.rstrip('/')
    if url.startswith('/'):
        # Absolute path
        parsed = urllib.parse.urlparse(base)
        return f"{parsed.scheme}://{parsed.netloc}{url}"
    else:
        return f"{base}/{url}"


# ============================================================
# Markdown Escaping
# ============================================================

def escape_text(text, in_table=False):
    """Apply smart escaping to text content for markdown."""
    if not text:
        return text

    # Replace < and > with HTML entities
    text = text.replace('<', '&lt;').replace('>', '&gt;')

    # Escape backticks
    text = re.sub(r'`', r'\\`', text)

    return text


def escape_inline_text(text):
    """Smart escape text that may contain markdown special chars."""
    if not text:
        return text

    # Replace < > with HTML entities
    text = text.replace('<', '&lt;').replace('>', '&gt;')

    # Escape backticks always
    text = re.sub(r'`', r'\\`', text)

    # Escape [ when followed by content ] potentially
    # Actually [ always gets escaped
    # Smart escape: escape [ when it forms a link pattern [...](...) or [...]
    text = re.sub(r'\[', r'\\[', text)

    # Escape \ (backslash) -- but careful not to escape our own escapes
    # Actually backslash in the source text should be doubled
    # But we need to be careful here since we're building escape sequences

    return text


def apply_smart_escaping(text):
    """Apply smart escaping to plain text content.

    This handles all the markdown special chars that would change the meaning.
    """
    if not text:
        return text

    # < > become HTML entities
    result = text.replace('<', '&lt;').replace('>', '&gt;')

    # Backticks are always escaped
    result = result.replace('`', '\\`')

    # Escape [ to prevent link/image patterns
    result = result.replace('[', '\\[')

    # Escape \ (literal backslash)
    # Wait, we need to escape this FIRST before adding our own backslashes
    # Actually the original tool doesn't escape \ based on our test showing text with backslash \\
    # In HTML "\\" is two backslashes, and output was "\\\\" -> hmm
    # Actually our test showed "text with backslash \\" -> the HTML has one backslash which becomes two in output
    # This means single \ in HTML becomes \\ in markdown (escaped backslash)

    # NOTE: We need to escape the source \ first before adding our own escape chars
    # But we've already started adding \ in our escaping above... 
    # This is tricky. Let me handle it differently.

    return result


# ============================================================
# Markdown Generator
# ============================================================

class MarkdownContext:
    """Holds the current state during markdown generation."""
    def __init__(self):
        self.list_depth = 0
        self.list_type_stack = []  # 'ul' or 'ol'
        self.list_counter_stack = []  # for ordered lists
        self.in_blockquote = 0
        self.in_pre = False
        self.in_table = False
        self.domain = ''
        self.options = {}

    def copy(self):
        ctx = MarkdownContext()
        ctx.list_depth = self.list_depth
        ctx.list_type_stack = self.list_type_stack[:]
        ctx.list_counter_stack = self.list_counter_stack[:]
        ctx.in_blockquote = self.in_blockquote
        ctx.in_pre = self.in_pre
        ctx.in_table = self.in_table
        ctx.domain = self.domain
        ctx.options = self.options
        return ctx


BLOCK_TAGS = {
    'p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'blockquote', 'pre', 'hr',
    'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',
    'article', 'section', 'header', 'footer', 'nav', 'aside', 'main',
    'figure', 'figcaption', 'details', 'summary',
    'dl', 'dt', 'dd',
    'form', 'fieldset', 'legend',
}


def is_block(node):
    """Check if node is a block-level element."""
    return node.tag in BLOCK_TAGS


def get_language_from_node(node):
    """Extract programming language from code/pre class attribute."""
    # Check code class first
    cls = node.attrs.get('class', '')
    for part in cls.split():
        if part.startswith('language-'):
            return part[9:]
        if part.startswith('lang-'):
            return part[5:]
    # Check parent pre class
    if node.parent:
        parent_cls = node.parent.attrs.get('class', '')
        for part in parent_cls.split():
            if part.startswith('language-'):
                return part[9:]
            if part.startswith('lang-'):
                return part[5:]
    return ''


def normalize_whitespace(text):
    """Normalize whitespace in text (like HTML does)."""
    # Collapse all whitespace to single space
    return re.sub(r'\s+', ' ', text)


class MarkdownConverter:
    def __init__(self, domain='', options=None):
        self.domain = domain
        self.options = options or {}
        self.plugin_table = self.options.get('plugin_table', False)
        self.plugin_strikethrough = self.options.get('plugin_strikethrough', False)
        self.strong_delimiter = self.options.get('strong_delimiter', '**')
        # Table options
        self.table_cell_padding = self.options.get('table_cell_padding', 'aligned')
        self.table_header_promotion = self.options.get('table_header_promotion', False)
        self.table_newline_behavior = self.options.get('table_newline_behavior', 'skip')
        self.table_presentation_tables = self.options.get('table_presentation_tables', False)
        self.table_skip_empty_rows = self.options.get('table_skip_empty_rows', False)
        self.table_span_cell_behavior = self.options.get('table_span_cell_behavior', 'empty')

    def convert(self, root):
        """Convert DOM tree to markdown string."""
        parts = self._convert_children(root, {
            'list_depth': 0,
            'list_type_stack': [],
            'list_counter_stack': [],
            'in_blockquote': 0,
            'in_pre': False,
            'in_table': False,
        })
        result = parts
        # Clean up: trim multiple blank lines to max 2
        result = re.sub(r'\n{3,}', '\n\n', result)
        # Ensure single trailing newline
        result = result.rstrip('\n') + '\n'
        return result

    def _convert_children(self, node, ctx):
        """Convert all children of a node to markdown."""
        parts = []
        for child in node.children:
            part = self._convert_node(child, ctx)
            parts.append(part)
        return ''.join(parts)

    def _convert_node(self, node, ctx):
        """Convert a single node to markdown."""
        if node.tag == '#text':
            return self._convert_text(node, ctx)

        tag = node.tag

        # Skip elements
        if tag in SKIP_CONTENT_ELEMENTS:
            return ''

        # Headings
        if tag in ('h1', 'h2', 'h3', 'h4', 'h5', 'h6'):
            return self._convert_heading(node, ctx)

        # Paragraph
        if tag == 'p':
            return self._convert_paragraph(node, ctx)

        # Horizontal rule
        if tag == 'hr':
            return '\n\n* * *\n\n'

        # Line break
        if tag == 'br':
            return '  \n'

        # Strong/bold
        if tag in ('strong', 'b'):
            return self._convert_strong(node, ctx)

        # Emphasis/italic
        if tag in ('em', 'i'):
            return self._convert_em(node, ctx)

        # Inline code
        if tag in ('code', 'kbd', 'tt', 'var', 'samp'):
            if ctx.get('in_pre'):
                return self._convert_children(node, ctx)
            return self._convert_code(node, ctx)

        # Pre / code block
        if tag == 'pre':
            return self._convert_pre(node, ctx)

        # Links
        if tag == 'a':
            return self._convert_link(node, ctx)

        # Images
        if tag == 'img':
            return self._convert_img(node, ctx)

        # Blockquote
        if tag == 'blockquote':
            return self._convert_blockquote(node, ctx)

        # Lists
        if tag == 'ul':
            return self._convert_ul(node, ctx)

        if tag == 'ol':
            return self._convert_ol(node, ctx)

        if tag == 'li':
            return self._convert_li(node, ctx)

        # Strikethrough
        if tag in ('del', 's', 'strike'):
            if self.plugin_strikethrough:
                inner = self._convert_children(node, ctx)
                return f'~~{inner}~~'
            else:
                return self._convert_children(node, ctx)

        # Table
        if tag == 'table':
            return self._convert_table(node, ctx)

        if tag in ('thead', 'tbody', 'tfoot'):
            return self._convert_children(node, ctx)

        if tag in ('tr', 'th', 'td'):
            # These are handled by _convert_table
            return self._convert_children(node, ctx)

        # Definition list
        if tag == 'dl':
            return self._convert_block_element(node, ctx)

        if tag == 'dt':
            inner = self._convert_children(node, ctx).strip()
            return f'\n{inner}\n'

        if tag == 'dd':
            inner = self._convert_children(node, ctx).strip()
            return f'\n{inner}\n'

        # Figure
        if tag == 'figure':
            return self._convert_block_element(node, ctx)

        if tag == 'figcaption':
            inner = self._convert_children(node, ctx).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        # Details/Summary
        if tag == 'details':
            return self._convert_block_element(node, ctx)

        if tag == 'summary':
            inner = self._convert_children(node, ctx).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        # Block elements that just pass through
        if tag in BLOCK_TAGS:
            return self._convert_block_element(node, ctx)

        # Inline elements that pass through
        return self._convert_children(node, ctx)

    def _convert_text(self, node, ctx):
        """Convert a text node."""
        text = node.text_content

        if ctx.get('in_pre'):
            return text

        if ctx.get('in_table_cell'):
            # Normalize whitespace in table cells
            text = normalize_whitespace(text)
            text = self._escape_text_smart(text, in_table=True)
            return text

        # Normalize whitespace
        text = normalize_whitespace(text)

        if not text or text == ' ':
            # Return space only if it's between inline elements
            return text

        return self._escape_text_smart(text)

    def _escape_text_smart(self, text, in_table=False):
        """Apply smart escaping to text."""
        if not text:
            return text

        # Replace < and > with HTML entities first
        text = text.replace('<', '&lt;').replace('>', '&gt;')

        # Escape backslashes first (before adding our own)
        text = text.replace('\\', '\\\\')

        # Escape backticks
        text = text.replace('`', '\\`')

        # Escape [ to prevent link patterns
        text = text.replace('[', '\\[')

        return text

    def _apply_line_escaping(self, text):
        """Apply start-of-line escaping to text."""
        lines = text.split('\n')
        result_lines = []
        for line in lines:
            line = self._escape_line_start(line)
            result_lines.append(line)
        return '\n'.join(result_lines)

    def _escape_line_start(self, line):
        """Escape characters at the start of a line that would be markdown syntax."""
        # Heading: # at start followed by space
        if re.match(r'^#{1,6} ', line):
            line = '\\' + line
        # Unordered list: - , +, * at start followed by space
        elif re.match(r'^[-+*] ', line) or re.match(r'^[-+*]$', line):
            line = '\\' + line
        # Ordered list: number followed by . or ) at start
        elif re.match(r'^\d+[.)]\s', line) or re.match(r'^\d+[.)]$', line):
            idx = line.index('.') if '.' in line[:5] else line.index(')')
            line = line[:idx] + '\\' + line[idx:]
        # Setext-style heading: --- (only dashes, could be setext h2 or hr)
        # We need to escape lines that are only dashes (would create hr or setext heading)
        elif re.match(r'^-+$', line):
            line = '\\' + line

        return line

    def _convert_heading(self, node, ctx):
        """Convert heading element."""
        level = int(node.tag[1])
        prefix = '#' * level
        inner = self._convert_children(node, ctx).strip()
        return f'\n\n{prefix} {inner}\n\n'

    def _convert_paragraph(self, node, ctx):
        """Convert paragraph element."""
        inner = self._convert_children(node, ctx).strip()
        if not inner:
            return ''
        # Apply line escaping
        inner = self._apply_line_escaping(inner)
        return f'\n\n{inner}\n\n'

    def _convert_strong(self, node, ctx):
        """Convert strong/bold element."""
        inner = self._convert_children(node, ctx)
        if not inner.strip():
            return inner
        d = self.strong_delimiter
        return f'{d}{inner}{d}'

    def _convert_em(self, node, ctx):
        """Convert em/italic element."""
        inner = self._convert_children(node, ctx)
        if not inner.strip():
            return inner
        return f'*{inner}*'

    def _convert_code(self, node, ctx):
        """Convert inline code element."""
        # Get text content (raw, no escaping for code)
        content = node.text_content_of()

        if not content:
            return ''

        # Find the longest run of backticks in content
        max_backticks = 0
        count = 0
        for c in content:
            if c == '`':
                count += 1
                max_backticks = max(max_backticks, count)
            else:
                count = 0

        # Use one more backtick than the max run
        n = max_backticks + 1
        delim = '`' * n

        # Add space padding if content starts or ends with backtick
        if content.startswith('`') or content.endswith('`'):
            return f'{delim} {content} {delim}'

        return f'{delim}{content}{delim}'

    def _convert_pre(self, node, ctx):
        """Convert pre/code block element."""
        # Find language
        lang = ''

        # Check if there's a code child
        code_child = None
        for child in node.children:
            if child.tag == 'code':
                code_child = child
                break

        if code_child:
            lang = get_language_from_node(code_child)
            if not lang:
                lang = get_language_from_node(node)
        else:
            lang = get_language_from_node(node)

        # Get content (with preserved whitespace)
        new_ctx = dict(ctx)
        new_ctx['in_pre'] = True

        if code_child:
            content = self._convert_children(code_child, new_ctx)
        else:
            content = self._convert_children(node, new_ctx)

        # Remove trailing newline from content if present (it goes before ```)
        # Actually keep the content as-is

        return f'\n\n```{lang}\n{content}```\n\n'

    def _convert_link(self, node, ctx):
        """Convert anchor element."""
        href = node.attrs.get('href', '')
        title = node.attrs.get('title', '')

        # Resolve relative URL
        href = resolve_url(href, self.domain)

        # Encode URL
        href = encode_url(href)

        inner = self._convert_children(node, ctx)

        if title:
            return f'[{inner}]({href} "{title}")'
        return f'[{inner}]({href})'

    def _convert_img(self, node, ctx):
        """Convert image element."""
        src = node.attrs.get('src', '')
        alt = node.attrs.get('alt', '')
        title = node.attrs.get('title', '')

        if not src:
            return ''

        # Resolve relative URL
        src = resolve_url(src, self.domain)

        # Encode URL
        src = encode_url(src)

        if title:
            return f'![{alt}]({src} "{title}")'
        return f'![{alt}]({src})'

    def _convert_blockquote(self, node, ctx):
        """Convert blockquote element."""
        new_ctx = dict(ctx)
        new_ctx['in_blockquote'] = ctx.get('in_blockquote', 0) + 1

        inner = self._convert_children(node, new_ctx)
        inner = inner.strip('\n')

        # Prefix each line with >
        lines = inner.split('\n')
        prefixed = []
        for line in lines:
            prefixed.append('> ' + line if line else '>')
        result = '\n'.join(prefixed)

        return f'\n\n{result}\n\n'

    def _convert_ul(self, node, ctx):
        """Convert unordered list."""
        new_ctx = dict(ctx)
        new_ctx['list_depth'] = ctx.get('list_depth', 0) + 1
        new_ctx['list_type'] = 'ul'
        new_ctx['list_counter'] = 0

        items = []
        for child in node.children:
            if child.tag == 'li':
                items.append(self._convert_li_item(child, new_ctx, 'ul'))

        result = '\n'.join(items)
        depth = ctx.get('list_depth', 0)
        if depth == 0:
            return f'\n\n{result}\n\n'
        else:
            return f'\n\n{result}\n'

    def _convert_ol(self, node, ctx):
        """Convert ordered list."""
        new_ctx = dict(ctx)
        new_ctx['list_depth'] = ctx.get('list_depth', 0) + 1
        new_ctx['list_type'] = 'ol'
        new_ctx['list_counter'] = 0

        items = []
        counter = 1
        for child in node.children:
            if child.tag == 'li':
                items.append(self._convert_li_item(child, new_ctx, 'ol', counter))
                counter += 1

        result = '\n'.join(items)
        depth = ctx.get('list_depth', 0)
        if depth == 0:
            return f'\n\n{result}\n\n'
        else:
            return f'\n\n{result}\n'

    def _convert_li_item(self, node, ctx, list_type, counter=1):
        """Convert a list item."""
        depth = ctx.get('list_depth', 1)
        indent = '  ' * (depth - 1)

        if list_type == 'ul':
            prefix = f'{indent}- '
        else:
            prefix = f'{indent}{counter}. '

        # Check if li contains block elements
        has_block = any(c.tag in BLOCK_TAGS for c in node.children if c.tag != '#text')

        new_ctx = dict(ctx)
        inner = self._convert_children(node, new_ctx)
        inner = inner.strip('\n')

        if has_block or '\n\n' in inner:
            # Multi-paragraph list item
            lines = inner.split('\n')
            result_lines = []
            first = True
            for i, line in enumerate(lines):
                if first:
                    result_lines.append(prefix + line)
                    first = False
                else:
                    if line:
                        result_lines.append('  ' * depth + line)
                    else:
                        result_lines.append('')
            return '\n'.join(result_lines)
        else:
            inner = inner.strip()
            return prefix + inner

    def _convert_li(self, node, ctx):
        """Convert li (when not processed by list handler - shouldn't happen normally)."""
        return self._convert_children(node, ctx)

    def _convert_block_element(self, node, ctx):
        """Convert a generic block element."""
        inner = self._convert_children(node, ctx)
        # Block elements need blank lines around them
        inner = inner.strip('\n')
        if not inner:
            return ''
        return f'\n\n{inner}\n\n'

    def _convert_table(self, node, ctx):
        """Convert table element."""
        if not self.plugin_table:
            # Without table plugin, just render content
            return self._convert_block_element(node, ctx)

        # Check if it's a presentation table
        role = node.attrs.get('role', '')
        if role == 'presentation' and not self.table_presentation_tables:
            return self._convert_block_element(node, ctx)

        # Parse the table
        rows = self._parse_table(node)

        if not rows:
            return ''

        return self._render_table(rows, node) 

    def _parse_table(self, table_node):
        """Parse table into a 2D array of cells."""
        all_rows = []
        header_rows = []
        body_rows = []

        def process_rows(parent, is_header=False):
            for child in parent.children:
                if child.tag == 'tr':
                    row = []
                    for cell in child.children:
                        if cell.tag in ('th', 'td'):
                            colspan = int(cell.attrs.get('colspan', 1))
                            rowspan = int(cell.attrs.get('rowspan', 1))
                            is_th = cell.tag == 'th'

                            new_ctx = {'in_table_cell': True, 'in_pre': False}

                            # Handle newlines in table cells
                            if self.table_newline_behavior == 'preserve':
                                content = self._convert_children_for_table_cell(cell)
                            else:
                                content = self._convert_children_for_table_cell(cell)
                                # Strip newlines for 'skip'
                                if self.table_newline_behavior == 'skip':
                                    content = content.replace('\n', ' ')

                            row.append({
                                'content': content.strip(),
                                'colspan': colspan,
                                'rowspan': rowspan,
                                'is_header': is_th or is_header,
                            })
                    if row:
                        if is_header:
                            header_rows.append(row)
                        else:
                            body_rows.append(row)
                elif child.tag in ('thead', 'tbody', 'tfoot'):
                    process_rows(child, child.tag == 'thead')

        process_rows(table_node)

        all_rows = header_rows + body_rows
        return all_rows, header_rows, body_rows

    def _convert_children_for_table_cell(self, node):
        """Convert table cell children, handling br specially."""
        parts = []
        for child in node.children:
            if child.tag == 'br':
                if self.table_newline_behavior == 'preserve':
                    parts.append('  <br />')
                else:
                    parts.append('\n')
            elif child.tag == '#text':
                text = normalize_whitespace(child.text_content)
                text = self._escape_text_smart(text, in_table=True)
                parts.append(text)
            else:
                parts.append(self._convert_node(child, {'in_table_cell': True}))
        return ''.join(parts)

    def _render_table(self, rows_data, table_node):
        """Render table to markdown."""
        all_rows, header_rows, body_rows = rows_data

        if not all_rows:
            return ''

        # Determine number of columns
        num_cols = max(
            sum(cell.get('colspan', 1) for cell in row)
            for row in all_rows
        ) if all_rows else 0

        if num_cols == 0:
            return ''

        # Handle span cells
        grid = []
        for row in all_rows:
            expanded_row = []
            for cell in row:
                colspan = cell.get('colspan', 1)
                content = cell['content']
                expanded_row.append(content)
                for i in range(colspan - 1):
                    if self.table_span_cell_behavior == 'mirror':
                        expanded_row.append(content)
                    else:
                        expanded_row.append('')
            # Pad to num_cols
            while len(expanded_row) < num_cols:
                expanded_row.append('')
            expanded_row = expanded_row[:num_cols]
            grid.append(expanded_row)

        # Determine header rows
        if header_rows:
            n_header = len(header_rows)
        elif self.table_header_promotion and body_rows:
            n_header = 1
        else:
            n_header = 0

        # Skip empty rows
        if self.table_skip_empty_rows:
            new_grid = []
            for i, row in enumerate(grid):
                if i < n_header or any(c.strip() for c in row):
                    new_grid.append(row)
            # Re-check header
            grid = new_grid

        if not grid:
            return ''

        # If no header rows, add empty header row
        if n_header == 0:
            header_row = [''] * num_cols
            grid = [header_row] + grid
            n_header = 1

        # Calculate column widths
        col_widths = [0] * num_cols
        for row in grid:
            for j, cell in enumerate(row):
                if j < num_cols:
                    col_widths[j] = max(col_widths[j], len(cell))

        # Ensure minimum width of 3 (for ---)
        col_widths = [max(w, 3) for w in col_widths]

        # Build table lines
        lines = []

        padding = self.table_cell_padding

        for i, row in enumerate(grid):
            cells = row[:num_cols]
            # Pad cells list
            while len(cells) < num_cols:
                cells.append('')

            if padding == 'none':
                line = '|' + '|'.join(cells) + '|'
            elif padding in ('minimal', 'aligned'):
                formatted = []
                for j, cell in enumerate(cells):
                    if padding == 'aligned':
                        formatted.append(f' {cell:<{col_widths[j]}} ')
                    else:  # minimal
                        formatted.append(f' {cell} ')
                line = '|' + '|'.join(formatted) + '|'

            lines.append(line)

            # Add separator after header rows
            if i == n_header - 1:
                if padding == 'none':
                    sep_cells = ['-' * 3 for _ in range(num_cols)]
                    sep = '|' + '|'.join(sep_cells) + '|'
                elif padding == 'aligned':
                    sep_cells = ['-' * (col_widths[j] + 2) for j in range(num_cols)]
                    sep = '|' + '|'.join(sep_cells) + '|'
                else:  # minimal
                    sep_cells = ['---' for _ in range(num_cols)]
                    sep = '|' + '|'.join(sep_cells) + '|'
                lines.append(sep)

        result = '\n'.join(lines)
        return f'\n\n{result}\n\n'


def convert_html_to_markdown(html_str, domain='', options=None,
                              include_selectors=None, exclude_selectors=None):
    """Main conversion function."""
    root = parse_html(html_str)

    # Apply selectors
    root = filter_nodes(root, include_selectors, exclude_selectors)

    # Convert
    converter = MarkdownConverter(domain=domain, options=options)
    return converter.convert(root)


