def parse_args(args):
    """Parse command line arguments."""
    result = {
        'version': False,
        'help': False,
        'input': None,
        'output': None,
        'output_overwrite': False,
        'domain': '',
        'exclude_selectors': [],
        'include_selectors': [],
        'strong_delimiter': '**',
        'table_cell_padding': 'aligned',
        'table_header_promotion': False,
        'table_newline_behavior': 'skip',
        'table_presentation_tables': False,
        'table_skip_empty_rows': False,
        'table_span_cell_behavior': 'empty',
        'plugin_strikethrough': False,
        'plugin_table': False,
    }

    i = 0
    while i < len(args):
        arg = args[i]

        if arg in ('-v', '--version'):
            result['version'] = True
        elif arg == '--help':
            result['help'] = True
        elif arg == '--output-overwrite':
            result['output_overwrite'] = True
        elif arg == '--opt-table-header-promotion':
            result['table_header_promotion'] = True
        elif arg == '--opt-table-presentation-tables':
            result['table_presentation_tables'] = True
        elif arg == '--opt-table-skip-empty-rows':
            result['table_skip_empty_rows'] = True
        elif arg == '--plugin-strikethrough':
            result['plugin_strikethrough'] = True
        elif arg == '--plugin-table':
            result['plugin_table'] = True
        elif '=' in arg and arg.startswith('--'):
            key, val = arg.split('=', 1)
            if key == '--input':
                result['input'] = val
            elif key == '--output':
                result['output'] = val
            elif key == '--domain':
                result['domain'] = val
            elif key == '--exclude-selector':
                result['exclude_selectors'].append(val)
            elif key == '--include-selector':
                result['include_selectors'].append(val)
            elif key == '--opt-strong-delimiter':
                result['strong_delimiter'] = val
            elif key == '--opt-table-cell-padding-behavior':
                result['table_cell_padding'] = val
            elif key == '--opt-table-newline-behavior':
                result['table_newline_behavior'] = val
            elif key == '--opt-table-span-cell-behavior':
                result['table_span_cell_behavior'] = val
            else:
                print(f'\nerror: unknown flag: {key}\n', file=sys.stderr)
                sys.exit(1)
        elif arg.startswith('--'):
            # Check if next arg is the value
            if i + 1 < len(args) and not args[i+1].startswith('--'):
                # Could be: --flag value format
                pass
            print(f'\nerror: unknown flag: {arg}\n', file=sys.stderr)
            sys.exit(1)
        else:
            print(f'\nerror: unknown argument: {arg}\n', file=sys.stderr)
            sys.exit(1)

        i += 1

    return result


def process_file(input_path, output_path, opts):
    """Process a single HTML file."""
    with open(input_path, 'r', encoding='utf-8', errors='replace') as f:
        html_content = f.read()

    options = {
        'plugin_table': opts['plugin_table'],
        'plugin_strikethrough': opts['plugin_strikethrough'],
        'strong_delimiter': opts['strong_delimiter'],
        'table_cell_padding': opts['table_cell_padding'],
        'table_header_promotion': opts['table_header_promotion'],
        'table_newline_behavior': opts['table_newline_behavior'],
        'table_presentation_tables': opts['table_presentation_tables'],
        'table_skip_empty_rows': opts['table_skip_empty_rows'],
        'table_span_cell_behavior': opts['table_span_cell_behavior'],
    }

    markdown = convert_html_to_markdown(
        html_content,
        domain=opts['domain'],
        options=options,
        include_selectors=opts['include_selectors'] or None,
        exclude_selectors=opts['exclude_selectors'] or None,
    )

    if output_path:
        if os.path.exists(output_path) and not opts['output_overwrite']:
            print(f'\nerror: output path "{output_path}" already exists. Use --output-overwrite to replace existing files\n', file=sys.stderr)
            sys.exit(1)
        os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write(markdown)
    else:
        sys.stdout.write(markdown)


def main():
    args = sys.argv[1:]
    opts = parse_args(args)

    if opts['version']:
        print(VERSION_INFO)
        sys.exit(0)

    if opts['help']:
        print(HELP_TEXT)
        sys.exit(0)

    input_path = opts['input']
    output_path = opts['output']

    if input_path:
        # Check if it's a directory
        if os.path.isdir(input_path):
            print(f'\nerror: input path "{input_path}" is a directory, not a file\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input "src/*.html" --output "dist/"\n', file=sys.stderr)
            sys.exit(1)

        # Check if it contains glob patterns
        if '*' in input_path or '?' in input_path or '[' in input_path:
            # Glob pattern
            files = sorted(glob.glob(input_path))
            if not files:
                print(f'\nerror: no files found matching pattern "{input_path}"\n', file=sys.stderr)
                sys.exit(1)

            if not output_path:
                print(f'\nerror: --output is required when using glob patterns\n', file=sys.stderr)
                sys.exit(1)

            if not os.path.isdir(output_path) and not output_path.endswith('/'):
                os.makedirs(output_path, exist_ok=True)

            for f in files:
                basename = os.path.basename(f)
                name_no_ext = os.path.splitext(basename)[0]
                out_file = os.path.join(output_path, name_no_ext + '.md')
                process_file(f, out_file, opts)
        else:
            # Single file
            process_file(input_path, output_path, opts)
    else:
        # Read from stdin
        html_content = sys.stdin.read()

        options = {
            'plugin_table': opts['plugin_table'],
            'plugin_strikethrough': opts['plugin_strikethrough'],
            'strong_delimiter': opts['strong_delimiter'],
            'table_cell_padding': opts['table_cell_padding'],
            'table_header_promotion': opts['table_header_promotion'],
            'table_newline_behavior': opts['table_newline_behavior'],
            'table_presentation_tables': opts['table_presentation_tables'],
            'table_skip_empty_rows': opts['table_skip_empty_rows'],
            'table_span_cell_behavior': opts['table_span_cell_behavior'],
        }

        markdown = convert_html_to_markdown(
            html_content,
            domain=opts['domain'],
            options=options,
            include_selectors=opts['include_selectors'] or None,
            exclude_selectors=opts['exclude_selectors'] or None,
        )

        if output_path:
            if os.path.exists(output_path) and not opts['output_overwrite']:
                print(f'\nerror: output path "{output_path}" already exists. Use --output-overwrite to replace existing files\n', file=sys.stderr)
                sys.exit(1)
            with open(output_path, 'w', encoding='utf-8') as f:
                f.write(markdown)
        else:
            sys.stdout.write(markdown)


if __name__ == '__main__':
    main()
