        kwargs2['in_pre'] = False
        inner = self._convert_children(node, **kwargs2).strip()
        return f'\n\n{prefix} {inner}\n\n'

    def _paragraph(self, node, **kwargs):
        kwargs2 = dict(kwargs)
        kwargs2['in_pre'] = False
        inner = self._convert_children(node, **kwargs2).strip()
        if not inner:
