    def text_content_of(self):
        """Get all text content of this node."""
        if self.tag == '#text':
            return self.text_content
        return ''.join(c.text_content_of() for c in self.children)

    def __repr__(self):
        if self.tag == '#text':
            return f'Text({repr(self.text_content[:20])})'
        return f'<{self.tag}>'


# ============================================================
# HTML Parser
# ============================================================

VOID_ELEMENTS = frozenset({
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
})

RAW_TEXT_ELEMENTS = frozenset({'script', 'style', 'head'})


class HTMLDOMParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node('root')
        self.stack = [self.root]
        self._skip_depth = 0

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {k.lower(): (v or '') for k, v in attrs}
        node = Node(tag, attrs_dict)
        self.stack[-1].append_child(node)
        if tag in RAW_TEXT_ELEMENTS:
            self._skip_depth += 1
        if tag not in VOID_ELEMENTS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in VOID_ELEMENTS:
            return
        if tag in RAW_TEXT_ELEMENTS:
            self._skip_depth = max(0, self._skip_depth - 1)
        # Pop stack to matching open tag
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        if self._skip_depth > 0:
            return
        node = Node('#text')
        node.text_content = data
        self.stack[-1].append_child(node)


def parse_html(html_str):
    """Parse HTML string and return root DOM node."""
    parser = HTMLDOMParser()
    parser.feed(html_str)
    return parser.root


# ============================================================
# CSS Selector Engine
# ============================================================

def matches_selector(node, selector_str):
    """Check if a node matches a CSS selector string."""
    if node.tag == '#text':
        return False

    # Split by comma
    groups = _split_selector_groups(selector_str)
    for group in groups:
        if _matches_selector_group(node, group.strip()):
            return True
    return False


def _split_selector_groups(s):
    """Split selector by comma, respecting brackets."""
    groups = []
    depth = 0
    current = []
    for c in s:
        if c == '[':
            depth += 1
            current.append(c)
        elif c == ']':
            depth -= 1
            current.append(c)
        elif c == ',' and depth == 0:
            groups.append(''.join(current))
            current = []
        else:
            current.append(c)
    if current:
        groups.append(''.join(current))
    return groups


def _matches_selector_group(node, selector):
    """Match a node against a single selector group (no commas)."""
    # Tokenize: split by combinators
    parts = _tokenize_selector(selector)
    if not parts:
        return False
    return _match_parts(node, parts)


def _tokenize_selector(s):
    """Tokenize selector into list of (combinator, simple_selector) tuples."""
    tokens = []
    i = 0
    s = s.strip()
    pending_combinator = None  # None means "start"

    while i < len(s):
        # Skip whitespace
        if s[i] == ' ':
            # Whitespace = descendant combinator (if followed by simple sel)
            i += 1
            while i < len(s) and s[i] == ' ':
                i += 1
            if i < len(s) and s[i] not in '>+~':
                if pending_combinator is None:
                    pending_combinator = ' '
                else:
                    pending_combinator = ' '
            continue

        if s[i] in '>+~':
            pending_combinator = s[i]
            i += 1
            while i < len(s) and s[i] == ' ':
                i += 1
            continue

        # Parse simple selector
        j = i
        depth = 0
        while j < len(s):
            if s[j] == '[':
                depth += 1
            elif s[j] == ']':
                depth -= 1
            elif depth == 0 and (s[j] in ' >+~'):
                break
            j += 1

        simple = _parse_simple_selector(s[i:j])
        combinator = pending_combinator if pending_combinator is not None else (None if not tokens else ' ')
        tokens.append((combinator, simple))
        pending_combinator = None
        i = j

    return tokens


def _parse_simple_selector(s):
    """Parse a simple selector string into a dict."""
    result = {'tag': None, 'id': None, 'classes': [], 'attrs': [], 'pseudo': []}

    i = 0
    # Tag or * (universal)
    if i < len(s) and s[i] not in '.#[:*':
        j = i
        while j < len(s) and s[j] not in '.#[:':
            j += 1
        tag = s[i:j].lower()
        if tag:
            result['tag'] = tag
        i = j
    elif i < len(s) and s[i] == '*':
        i += 1  # universal selector

    while i < len(s):
        c = s[i]
        if c == '.':
            i += 1
            j = i
            while j < len(s) and s[j] not in '.#[:':
                j += 1
            result['classes'].append(s[i:j])
            i = j
        elif c == '#':
            i += 1
            j = i
            while j < len(s) and s[j] not in '.#[:':
                j += 1
            result['id'] = s[i:j]
            i = j
        elif c == '[':
            i += 1
            j = s.index(']', i)
            attr_str = s[i:j]
            i = j + 1
            attr_op, attr_name, attr_val = _parse_attr_selector(attr_str)
            result['attrs'].append((attr_op, attr_name, attr_val))
        elif c == ':':
            # Pseudo-class/element - skip
            i += 1
            j = i
            depth = 0
            while j < len(s):
                if s[j] == '(':
                    depth += 1
                elif s[j] == ')':
                    depth -= 1
                    if depth <= 0:
                        j += 1
                        break
                elif depth == 0 and s[j] in '.#[:':
                    break
                j += 1
            i = j
        else:
            i += 1

    return result


def _parse_attr_selector(s):
    """Parse attribute selector content (inside [])."""
    s = s.strip()
    for op in ('*=', '~=', '^=', '$=', '|=', '='):
        if op in s:
            k, v = s.split(op, 1)
            return (op, k.strip(), v.strip().strip('"\''))
    return ('exist', s.strip(), '')


def _match_simple(node, sel):
    """Check if node matches a simple selector."""
    if node.tag == '#text':
        return False
    if sel['tag'] and node.tag != sel['tag']:
        return False
    if sel['id'] is not None:
        if node.attrs.get('id', '') != sel['id']:
            return False
    node_classes = node.get_classes()
    for cls in sel['classes']:
        if cls not in node_classes:
            return False
    for op, attr, val in sel['attrs']:
        node_val = node.attrs.get(attr)
        if op == 'exist':
            if node_val is None:
                return False
        elif node_val is None:
            return False
        elif op == '=':
            if node_val != val:
                return False
        elif op == '*=':
            if val not in node_val:
                return False
        elif op == '^=':
            if not node_val.startswith(val):
                return False
        elif op == '$=':
            if not node_val.endswith(val):
                return False
        elif op == '~=':
            if val not in node_val.split():
                return False
        elif op == '|=':
            if node_val != val and not node_val.startswith(val + '-'):
                return False
    return True


def _match_parts(node, parts):
    """Recursively check if node matches selector parts."""
    if not parts:
        return False

    combinator, simple = parts[-1]

    if not _match_simple(node, simple):
        return False

    if len(parts) == 1:
        return True

    rest = parts[:-1]
    # The combinator is the one between rest[-1] and parts[-1]
    # It's stored in parts[-1]'s combinator field

    if combinator == ' ':
        # Descendant: any ancestor must match
        ancestor = node.parent
        while ancestor and ancestor.tag != 'root':
            if _match_parts(ancestor, rest):
                return True
            ancestor = ancestor.parent
        return False
    elif combinator == '>':
        # Child: direct parent must match
        if node.parent:
            return _match_parts(node.parent, rest)
        return False
    elif combinator == '+':
        # Adjacent sibling
        if node.parent:
            siblings = [c for c in node.parent.children if c.tag != '#text']
            idx = next((i for i, c in enumerate(siblings) if c is node), -1)
            if idx > 0:
                return _match_parts(siblings[idx - 1], rest)
        return False
    elif combinator == '~':
        # General sibling
        if node.parent:
            siblings = [c for c in node.parent.children if c.tag != '#text']
            idx = next((i for i, c in enumerate(siblings) if c is node), -1)
            for i in range(idx):
                if _match_parts(siblings[i], rest):
                    return True
        return False
    elif combinator is None:
        # First selector, no combinator
        return True

    return False


def find_matching_nodes(root, selector_str):
    """Find all nodes matching the selector."""
    results = []

    def traverse(node):
        if node.tag != '#text' and node.tag != 'root':
            if matches_selector(node, selector_str):
                results.append(node)
        for child in node.children:
            traverse(child)

    traverse(root)
    return results


def apply_selectors(root, include_selectors=None, exclude_selectors=None):
    """Apply include/exclude selectors to the DOM tree."""
    if include_selectors:
        matched = []
        for sel in include_selectors:
            matched.extend(find_matching_nodes(root, sel))

        new_root = Node('root')
        for node in matched:
            # Detach from parent to avoid duplicates in output
            node_copy = node  # shallow ref, we just re-parent it
            new_root.append_child(node)
        return new_root

    if exclude_selectors:
        excluded = set()
        for sel in exclude_selectors:
            for node in find_matching_nodes(root, sel):
                excluded.add(id(node))

        def remove_excluded(node):
            node.children = [c for c in node.children if id(c) not in excluded]
            for child in node.children:
                remove_excluded(child)

        remove_excluded(root)

    return root


# ============================================================
# URL Handling
# ============================================================

def encode_markdown_url(url):
    """Encode characters in URL that would break markdown syntax."""
    if not url:
        return url
    # In markdown link syntax: [text](URL), the URL can't contain unescaped ( or )
    # Also [ and ] break things
    # We use percent-encoding for these
    result = []
    for c in url:
        if c == '(':
            result.append('%28')
        elif c == ')':
            result.append('%29')
        elif c == '[':
            result.append('%5B')
        elif c == ']':
            result.append('%5D')
        elif c == ' ':
            result.append('%20')
        elif c == '\\':
            result.append('%5C')
        else:
            result.append(c)
    return ''.join(result)


def resolve_url(url, domain):
    """Resolve a possibly-relative URL against a base domain."""
    if not url or not domain:
        return url
    # Already absolute
    if re.match(r'^[a-zA-Z][a-zA-Z0-9+\-.]*:', url):
        return url
    # Protocol-relative
    if url.startswith('//'):
        return url

    # Parse the domain to get scheme and netloc
    if '://' not in domain:
        domain = 'https://' + domain

    parsed_base = urllib.parse.urlparse(domain)
    base_scheme = parsed_base.scheme
    base_netloc = parsed_base.netloc
    base_path = parsed_base.path.rstrip('/')

    if url.startswith('/'):
        return f"{base_scheme}://{base_netloc}{url}"
    else:
        return f"{base_scheme}://{base_netloc}/{url}"


# ============================================================
# Text Escaping
# ============================================================

def escape_text_content(text, strikethrough_plugin=False):
    """Apply smart escaping to text content from HTML."""
    if not text:
        return text

    # Step 1: Escape backslashes (must be first to avoid double-escaping)
    text = text.replace('\\', '\\\\')

    # Step 2: Escape < and > as HTML entities
    text = text.replace('<', '&lt;').replace('>', '&gt;')

    # Step 3: Escape [ when followed by ] anywhere
    text = _escape_brackets(text)

    # Step 4: Escape * when followed by non-whitespace
    text = _escape_char_left_flanking(text, '*')

    # Step 5: Escape _ when followed by non-whitespace
    text = _escape_char_left_flanking(text, '_')

    # Step 6: Escape ~ when followed by non-whitespace (only with strikethrough plugin)
    if strikethrough_plugin:
        text = _escape_char_left_flanking(text, '~')

    # Step 7: Escape backticks
    text = _escape_backticks(text)

    return text


def _escape_brackets(text):
    """Escape [ when there is a ] after it."""
    if '[' not in text or ']' not in text:
        return text

    result = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == '[':
            # Check if there's a ] anywhere after
            if ']' in text[i+1:]:
                result.append('\\[')
            else:
                result.append('[')
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def _escape_char_left_flanking(text, char):
    """Escape char when it's followed by a non-whitespace character."""
    if char not in text:
        return text

    result = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == char:
            # Check what follows
            next_c = text[i+1] if i+1 < len(text) else ''
            if next_c and next_c not in ' \t\n\r':
                result.append('\\' + char)
            else:
                result.append(char)
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def _escape_backticks(text):
    """Escape backticks in text."""
    if '`' not in text:
        return text
    return text.replace('`', '\\`')


def apply_line_escaping(text):
    """Apply line-start escaping to prevent markdown block-level syntax."""
    lines = text.split('\n')
    result = []
    for line in lines:
        result.append(_escape_line(line))
    return '\n'.join(result)


def _escape_line(line):
    """Escape a single line's start if necessary."""
    if not line:
        return line

    # ATX heading: # followed by space (or more #s then space)
    if re.match(r'^#{1,6} ', line):
        return '\\' + line

    # Unordered list: -, +, or * followed by space OR just the char alone
    if re.match(r'^[-+*] ', line) or re.match(r'^[-+*]$', line):
        return '\\' + line

    # Ordered list: digits followed by . or ) with space, or digits+. alone
    if re.match(r'^\d+\. ', line) or re.match(r'^\d+\.$', line):
        m = re.match(r'^(\d+)(\.)', line)
        return line[:m.start(2)] + '\\' + line[m.start(2):]
    if re.match(r'^\d+\) ', line) or re.match(r'^\d+\)$', line):
        m = re.match(r'^(\d+)(\))', line)
        return line[:m.start(2)] + '\\' + line[m.start(2):]

    # Lines containing only dashes (3+): horizontal rule
    if re.match(r'^-{3,}$', line):
        return '\\' + line

    # Line of single dash: setext h2 underline
    if re.match(r'^-$', line):
        return '\\' + line

    # Fenced code block: ``` or ~~~  at start
    if re.match(r'^`{3,}', line):
        return '\\' + line[0] + line[1:]

    return line


# ============================================================
# Markdown Generator
# ============================================================

BLOCK_TAGS = frozenset({
    'p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'blockquote', 'pre', 'hr',
    'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',
    'article', 'section', 'header', 'footer', 'nav', 'aside', 'main',
    'figure', 'figcaption', 'details', 'summary',
    'dl', 'dt', 'dd',
    'form', 'fieldset', 'legend',
    'address', 'dialog',
})


def is_block_tag(tag):
    return tag in BLOCK_TAGS


def has_block_children(node):
    """Check if any direct children are block elements."""
    for child in node.children:
        if child.tag in BLOCK_TAGS:
            return True
    return False


def get_language_from_node(code_node, pre_node=None):
    """Extract programming language from code/pre class attribute."""
    # Check code node first
    for cls in code_node.get_classes():
        if cls.startswith('language-'):
            return cls[9:]
        if cls.startswith('lang-'):
            return cls[5:]
    # Check pre node
    if pre_node:
        for cls in pre_node.get_classes():
            if cls.startswith('language-'):
                return cls[9:]
            if cls.startswith('lang-'):
                return cls[5:]
    return ''


def normalize_whitespace(text):
    """Collapse whitespace (like HTML does)."""
    return re.sub(r'[ \t\r\n]+', ' ', text)


class Converter:
    def __init__(self, domain='', options=None):
        self.domain = domain
        options = options or {}
        self.plugin_table = options.get('plugin_table', False)
        self.plugin_strikethrough = options.get('plugin_strikethrough', False)
        self.strong_delimiter = options.get('strong_delimiter', '**')
        self.table_cell_padding = options.get('table_cell_padding', 'aligned')
        self.table_header_promotion = options.get('table_header_promotion', False)
        self.table_newline_behavior = options.get('table_newline_behavior', 'skip')
        self.table_presentation_tables = options.get('table_presentation_tables', False)
        self.table_skip_empty_rows = options.get('table_skip_empty_rows', False)
        self.table_span_cell_behavior = options.get('table_span_cell_behavior', 'empty')

    def convert(self, root):
        """Convert DOM tree to markdown."""
        result = self._convert_children(root, in_pre=False)
        # Clean up
        # Strip leading/trailing newlines, then add single trailing newline
        lines = result.split('\n')
        # Remove trailing spaces from each line EXCEPT lines with trailing "  " (br)
        clean_lines = []
        for line in lines:
            if line.endswith('  ') and not line.endswith('   '):
                # Preserve double-space line break marker
                clean_lines.append(line)
            else:
                clean_lines.append(line.rstrip())
        result = '\n'.join(clean_lines)
        # Collapse 3+ newlines to 2
        result = re.sub(r'\n{3,}', '\n\n', result)
        # Strip leading/trailing
        result = result.strip('\n')
        if result:
            result += '\n'
        return result

    def _convert_children(self, node, in_pre=False, in_list=False, list_indent='', 
                           in_blockquote=False, in_table_cell=False):
        parts = []
        for child in node.children:
            part = self._convert_node(child, in_pre=in_pre, in_list=in_list,
                                       list_indent=list_indent,
                                       in_blockquote=in_blockquote,
                                       in_table_cell=in_table_cell)
            parts.append(part)
        return ''.join(parts)

    def _convert_node(self, node, in_pre=False, in_list=False, list_indent='',
                      in_blockquote=False, in_table_cell=False):
        tag = node.tag

        if tag == '#text':
            return self._convert_text(node, in_pre=in_pre, in_table_cell=in_table_cell)

        # Skip content elements
        if tag in RAW_TEXT_ELEMENTS:
            return ''

        kwargs = dict(in_pre=in_pre, in_list=in_list, list_indent=list_indent,
                     in_blockquote=in_blockquote, in_table_cell=in_table_cell)

        if tag in ('h1', 'h2', 'h3', 'h4', 'h5', 'h6'):
            return self._heading(node, **kwargs)

        if tag == 'p':
            return self._paragraph(node, **kwargs)

        if tag == 'hr':
            return '\n\n* * *\n\n'

        if tag == 'br':
            if in_table_cell and self.table_newline_behavior == 'preserve':
                return '  <br />'
            return '  \n'

        if tag in ('strong', 'b'):
            return self._strong(node, **kwargs)

        if tag in ('em', 'i'):
            return self._em(node, **kwargs)

        if tag in ('code', 'kbd', 'tt', 'var', 'samp'):
            if in_pre:
                return self._convert_children(node, **kwargs)
            return self._inline_code(node)

        if tag == 'pre':
            return self._pre(node, **kwargs)

        if tag == 'a':
            return self._link(node, **kwargs)

        if tag == 'img':
            return self._img(node)

        if tag == 'blockquote':
            return self._blockquote(node, **kwargs)

        if tag == 'ul':
            return self._ul(node, **kwargs)

        if tag == 'ol':
            return self._ol(node, **kwargs)

        if tag == 'li':
            # This shouldn't normally be called directly
            return self._convert_children(node, **kwargs)

        if tag in ('del', 's', 'strike'):
            if self.plugin_strikethrough:
                inner = self._convert_children(node, **kwargs)
                return f'~~{inner}~~'
            return self._convert_children(node, **kwargs)

        if tag == 'table':
            return self._table(node, **kwargs)

        if tag in ('thead', 'tbody', 'tfoot'):
            # Handled by _table
            return ''

        if tag in ('tr', 'th', 'td'):
            # Handled by _table
            return ''

        if tag == 'dt':
            inner = self._convert_children(node, **kwargs).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag == 'dd':
            inner = self._convert_children(node, **kwargs).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag in ('figure', 'summary', 'details', 'dl', 'address'):
            return self._block_wrapper(node, **kwargs)

        if tag == 'figcaption':
            inner = self._convert_children(node, **kwargs).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag in BLOCK_TAGS:
            return self._block_wrapper(node, **kwargs)

        # Default: inline passthrough
        return self._convert_children(node, **kwargs)

    def _convert_text(self, node, in_pre=False, in_table_cell=False):
        text = node.text_content

        if in_pre:
            return text

        # Normalize whitespace
        text = normalize_whitespace(text)

        # Check if this is a whitespace-only text node in block context
        # We'll handle it by keeping spaces for inline context
        if not text.strip():
            return text  # keep space for inline, will be cleaned up

        # Apply smart escaping
        text = escape_text_content(text, self.plugin_strikethrough)

        return text

    def _heading(self, node, **kwargs):
        level = int(node.tag[1])
        prefix = '#' * level
        kwargs2 = dict(kwargs)
        kwargs2['in_pre'] = False
        inner = self._convert_children(node, **kwargs2).strip()
        return f'\n\n{prefix} {inner}\n\n'

    def _paragraph(self, node, **kwargs):
        kwargs2 = dict(kwargs)
        kwargs2['in_pre'] = False
        inner = self._convert_children(node, **kwargs2).strip()
        if not inner:
            return ''
        # Apply line-level escaping
        inner = apply_line_escaping(inner)
        return f'\n\n{inner}\n\n'

    def _strong(self, node, **kwargs):
        inner = self._convert_children(node, **kwargs)
        if not inner.strip():
            return inner
        d = self.strong_delimiter
        return f'{d}{inner}{d}'

    def _em(self, node, **kwargs):
        inner = self._convert_children(node, **kwargs)
        if not inner.strip():
            return inner
        return f'*{inner}*'

    def _inline_code(self, node):
        """Convert inline code element."""
        content = node.text_content_of()
        if not content:
            return ''

        # Find max consecutive backtick run in content
        max_run = 0
        run = 0
        for c in content:
            if c == '`':
                run += 1
                max_run = max(max_run, run)
            else:
                run = 0

        delim = '`' * (max_run + 1)

        # Add space padding if content starts or ends with backtick
        if content.startswith('`') or content.endswith('`'):
            return f'{delim} {content} {delim}'
        return f'{delim}{content}{delim}'

    def _pre(self, node, **kwargs):
        """Convert pre element (code block)."""
        # Find code child
        code_node = None
        for child in node.children:
            if child.tag == 'code':
                code_node = child
                break

        # Get language
        if code_node:
            lang = get_language_from_node(code_node, node)
        else:
            lang = get_language_from_node(node)

        # Get raw content
        if code_node:
            content = code_node.text_content_of()
        else:
            content = self._convert_children(node, in_pre=True)

        return f'\n\n```{lang}\n{content}```\n\n'

    def _link(self, node, **kwargs):
        href = node.attrs.get('href', '')
        title = node.attrs.get('title', '')

        href = resolve_url(href, self.domain)
        href = encode_markdown_url(href)

        inner = self._convert_children(node, **kwargs)

        if title:
            return f'[{inner}]({href} "{title}")'
        return f'[{inner}]({href})'

    def _img(self, node):
        src = node.attrs.get('src', '')
        alt = node.attrs.get('alt', '')
        title = node.attrs.get('title', '')

        if not src:
            return ''

        src = resolve_url(src, self.domain)
        src = encode_markdown_url(src)

        if title:
            return f'![{alt}]({src} "{title}")'
        return f'![{alt}]({src})'

    def _blockquote(self, node, **kwargs):
        kwargs2 = dict(kwargs)
        kwargs2['in_blockquote'] = True
        inner = self._convert_children(node, **kwargs2)
        inner = inner.strip('\n')

        # Prefix each line with "> "
        lines = inner.split('\n')
        prefixed = ['> ' + line if line else '>' for line in lines]
        result = '\n'.join(prefixed)

        return f'\n\n{result}\n\n'

    def _ul(self, node, **kwargs):
        return self._list(node, 'ul', **kwargs)

    def _ol(self, node, **kwargs):
        return self._list(node, 'ol', **kwargs)

    def _list(self, node, list_type, **kwargs):
        current_indent = kwargs.get('list_indent', '')
        new_indent = current_indent + '  '

        items = []
        counter = 1
        for child in node.children:
            if child.tag == 'li':
                if list_type == 'ul':
                    prefix = current_indent + '- '
                else:
                    prefix = f'{current_indent}{counter}. '
                    counter += 1

                item = self._list_item(child, prefix, new_indent, **kwargs)
                items.append(item)

        if not items:
            return ''

        result = '\n'.join(items)

        # Top-level list needs blank lines around it
        if not kwargs.get('in_list'):
            return f'\n\n{result}\n\n'
        else:
            # Nested list: return with newlines that will be handled by parent
            return f'\n\n{result}\n'

    def _list_item(self, node, prefix, indent, **kwargs):
        """Convert a list item."""
        # Check if item contains block elements
        has_block = any(c.tag in BLOCK_TAGS and c.tag not in ('ul', 'ol') 
                       for c in node.children if c.tag != '#text')

        kwargs2 = dict(kwargs)
        kwargs2['in_list'] = True
        kwargs2['list_indent'] = indent

        inner = self._convert_children(node, **kwargs2)
        inner = inner.strip('\n')

        if '\n\n' in inner or has_block:
            # Multi-block content: indent continuation lines
            lines = inner.split('\n')
            result_lines = []
            first = True
            for line in lines:
                if first:
                    result_lines.append(prefix + line)
                    first = False
                else:
                    if line:
                        result_lines.append(indent + line)
                    else:
                        result_lines.append('')
            return '\n'.join(result_lines)
        else:
            inner = inner.strip()
            # Apply line escaping to the content
            inner = apply_line_escaping(inner)
            return prefix + inner

    def _block_wrapper(self, node, **kwargs):
        """Convert a generic block element by wrapping content with blank lines."""
        inner = self._convert_children(node, **kwargs)
        inner = inner.strip('\n')
        if not inner:
            return ''
        return f'\n\n{inner}\n\n'

    def _table(self, node, **kwargs):
        """Convert table element."""
        if not self.plugin_table:
            return self._block_wrapper(node, **kwargs)

        # Check presentation tables
        role = node.attrs.get('role', '')
        if role == 'presentation' and not self.table_presentation_tables:
            return self._block_wrapper(node, **kwargs)

        return self._render_table(node)

    def _render_table(self, table_node):
        """Render a table to markdown."""
        # Parse table into rows
        header_rows, body_rows = self._parse_table_rows(table_node)

        all_rows = header_rows + body_rows
        if not all_rows:
            return ''

        # Determine number of columns
        def row_cols(row):
            return sum(c.get('colspan', 1) for c in row)
        num_cols = max(row_cols(r) for r in all_rows) if all_rows else 0
        if num_cols == 0:
            return ''

        # Expand colspan cells
        expanded_rows = []
        for row in all_rows:
            exp = []
            for cell in row:
                content = cell['content']
                colspan = cell.get('colspan', 1)
                exp.append(content)
                for _ in range(colspan - 1):
                    if self.table_span_cell_behavior == 'mirror':
                        exp.append(content)
                    else:
                        exp.append('')
            while len(exp) < num_cols:
                exp.append('')
            expanded_rows.append(exp[:num_cols])

        # Determine header row count
        n_header = len(header_rows)
        if n_header == 0 and self.table_header_promotion and body_rows:
            n_header = 1

        # Skip empty rows
        if self.table_skip_empty_rows:
            new_expanded = []
            n_skip = 0
            for i, row in enumerate(expanded_rows):
                if i < n_header:
                    new_expanded.append(row)
                elif any(c.strip() for c in row):
                    new_expanded.append(row)
                else:
                    if i < n_header + (n_skip := n_skip):
                        new_expanded.append(row)
            # Simpler implementation
            new_expanded2 = []
            for i, row in enumerate(expanded_rows):
                is_header = i < n_header
                if is_header or any(c.strip() for c in row):
                    new_expanded2.append(row)
            expanded_rows = new_expanded2

        # If no header, add empty header
        if n_header == 0:
            expanded_rows = [[''] * num_cols] + expanded_rows
            n_header = 1

        # Compute column widths
        col_widths = [max(len(row[j]) for row in expanded_rows if j < len(row)) 
                      for j in range(num_cols)]
        col_widths = [max(w, 3) for w in col_widths]

        # Render
        padding = self.table_cell_padding
        lines = []

        for i, row in enumerate(expanded_rows):
            cells = list(row) + [''] * (num_cols - len(row))
            cells = cells[:num_cols]

            if padding == 'none':
                line = '|' + '|'.join(cells) + '|'
            elif padding == 'aligned':
                formatted = [f' {c:<{col_widths[j]}} ' for j, c in enumerate(cells)]
                line = '|' + '|'.join(formatted) + '|'
            else:  # minimal
                formatted = [f' {c} ' for c in cells]
                line = '|' + '|'.join(formatted) + '|'

            lines.append(line)

            # Separator after header
            if i == n_header - 1:
                if padding == 'none':
                    sep = '|' + '|'.join(['---'] * num_cols) + '|'
                elif padding == 'aligned':
                    sep = '|' + '|'.join(['-' * (col_widths[j] + 2) for j in range(num_cols)]) + '|'
                else:  # minimal
                    sep = '|' + '|'.join(['---'] * num_cols) + '|'
                lines.append(sep)

        return '\n\n' + '\n'.join(lines) + '\n\n'

    def _parse_table_rows(self, table_node):
        """Parse table into header_rows and body_rows."""
        header_rows = []
        body_rows = []

        def process_section(section_node, is_header):
            for child in section_node.children:
                if child.tag == 'tr':
                    process_tr(child, is_header)
                elif child.tag in ('thead', 'tbody', 'tfoot'):
                    process_section(child, child.tag == 'thead')

        def process_tr(tr_node, is_header):
            row = []
            for cell in tr_node.children:
                if cell.tag in ('th', 'td'):
                    colspan = int(cell.attrs.get('colspan', 1))
                    rowspan = int(cell.attrs.get('rowspan', 1))
                    cell_is_header = cell.tag == 'th' or is_header

                    content = self._convert_table_cell(cell)
                    row.append({
                        'content': content,
                        'colspan': colspan,
                        'rowspan': rowspan,
                        'is_header': cell_is_header,
                    })
            if row:
                if is_header:
                    header_rows.append(row)
                else:
                    body_rows.append(row)

        for child in table_node.children:
            if child.tag == 'thead':
                process_section(child, True)
            elif child.tag == 'tbody':
                process_section(child, False)
            elif child.tag == 'tfoot':
                process_section(child, False)
            elif child.tag == 'tr':
                # th cells in a row with no thead = header
                has_th = any(c.tag == 'th' for c in child.children)
                process_tr(child, has_th)

        return header_rows, body_rows

    def _convert_table_cell(self, cell_node):
        """Convert cell content to a string for table."""
        parts = []
        for child in cell_node.children:
            if child.tag == 'br':
                if self.table_newline_behavior == 'preserve':
                    parts.append('  <br />')
                else:
                    parts.append('\n')
            elif child.tag == '#text':
                text = normalize_whitespace(child.text_content)
                text = escape_text_content(text.strip(), self.plugin_strikethrough)
                # Re-normalize: strip trailing/leading spaces we may have added
                parts.append(text)
            else:
                parts.append(self._convert_node(child, in_table_cell=True))

        content = ''.join(parts).strip()

        if self.table_newline_behavior == 'skip':
            content = content.replace('\n', ' ')

        return content


def html_to_markdown(html_str, domain='', options=None, 
                     include_selectors=None, exclude_selectors=None):
    """Main function: convert HTML to markdown."""
    root = parse_html(html_str)

    # Apply selectors
    root = apply_selectors(root, include_selectors, exclude_selectors)

    converter = Converter(domain=domain, options=options)
    return converter.convert(root)


