def parse_cli_args(argv):
    """Parse CLI arguments."""
    opts = {
        'version': False,
        'help': False,
        'input': None,
        'output': None,
        'output_overwrite': False,
        'domain': '',
        'exclude_selectors': [],
        'include_selectors': [],
        'strong_delimiter': '**',
        'table_cell_padding': 'aligned',
        'table_header_promotion': False,
        'table_newline_behavior': 'skip',
        'table_presentation_tables': False,
        'table_skip_empty_rows': False,
        'table_span_cell_behavior': 'empty',
        'plugin_strikethrough': False,
        'plugin_table': False,
    }

    i = 0
    while i < len(argv):
        arg = argv[i]

        if arg in ('-v', '--version'):
            opts['version'] = True
        elif arg == '--help':
            opts['help'] = True
        elif arg == '--output-overwrite':
            opts['output_overwrite'] = True
        elif arg == '--opt-table-header-promotion':
            opts['table_header_promotion'] = True
        elif arg == '--opt-table-presentation-tables':
            opts['table_presentation_tables'] = True
        elif arg == '--opt-table-skip-empty-rows':
            opts['table_skip_empty_rows'] = True
        elif arg == '--plugin-strikethrough':
            opts['plugin_strikethrough'] = True
        elif arg == '--plugin-table':
            opts['plugin_table'] = True
        elif arg.startswith('--') and '=' in arg:
            key, val = arg.split('=', 1)
            flag_map = {
                '--input': 'input',
                '--output': 'output',
                '--domain': 'domain',
                '--opt-strong-delimiter': 'strong_delimiter',
                '--opt-table-cell-padding-behavior': 'table_cell_padding',
                '--opt-table-newline-behavior': 'table_newline_behavior',
                '--opt-table-span-cell-behavior': 'table_span_cell_behavior',
            }
            if key == '--exclude-selector':
                opts['exclude_selectors'].append(val)
            elif key == '--include-selector':
                opts['include_selectors'].append(val)
            elif key in flag_map:
                opts[flag_map[key]] = val
            else:
                sys.stderr.write(f'\nerror: unknown flag: {key}\n\n')
                sys.exit(1)
        elif arg.startswith('--') or (arg.startswith('-') and len(arg) > 1 and arg[1] != '-'):
            sys.stderr.write(f'\nerror: unknown flag: {arg}\n\n')
            sys.exit(1)
        else:
            sys.stderr.write(f'\nerror: unknown argument: {arg}\n\n')
            sys.exit(1)

        i += 1

    return opts


def convert_file(input_path, options):
    """Read HTML from file and convert to markdown."""
    with open(input_path, 'r', encoding='utf-8', errors='replace') as f:
        return f.read()


def run(opts):
    """Execute the conversion based on parsed options."""
    conv_options = {
        'plugin_table': opts['plugin_table'],
        'plugin_strikethrough': opts['plugin_strikethrough'],
        'strong_delimiter': opts['strong_delimiter'],
        'table_cell_padding': opts['table_cell_padding'],
        'table_header_promotion': opts['table_header_promotion'],
        'table_newline_behavior': opts['table_newline_behavior'],
        'table_presentation_tables': opts['table_presentation_tables'],
        'table_skip_empty_rows': opts['table_skip_empty_rows'],
        'table_span_cell_behavior': opts['table_span_cell_behavior'],
    }
    inc_sel = opts['include_selectors'] or None
    exc_sel = opts['exclude_selectors'] or None

    input_path = opts['input']
    output_path = opts['output']

    def do_convert(html_content):
        return html_to_markdown(
            html_content,
            domain=opts['domain'],
            options=conv_options,
            include_selectors=inc_sel,
            exclude_selectors=exc_sel,
        )

    def write_output(content, out_path):
        if out_path:
            if os.path.exists(out_path) and not opts['output_overwrite']:
                sys.stderr.write(f'\nerror: output path "{out_path}" already exists. '
                               f'Use --output-overwrite to replace existing files\n\n')
                sys.exit(1)
            os.makedirs(os.path.dirname(os.path.abspath(out_path)), exist_ok=True)
            with open(out_path, 'w', encoding='utf-8') as f:
                f.write(content)
        else:
            sys.stdout.write(content)

    if input_path:
        if os.path.isdir(input_path):
            sys.stderr.write(
                f'\nerror: input path "{input_path}" is a directory, not a file\n\n'
                f'Here is how you can use a glob to match multiple files:\n\n'
                f'    html2markdown --input "src/*.html" --output "dist/"\n\n'
            )
            sys.exit(1)

        if any(c in input_path for c in '*?['):
            # Glob pattern
            files = sorted(glob.glob(input_path))
            if not files:
                sys.stderr.write(f'\nerror: no files found matching "{input_path}"\n\n')
                sys.exit(1)

            if not output_path:
                sys.stderr.write('\nerror: --output required for glob input\n\n')
                sys.exit(1)

            os.makedirs(output_path, exist_ok=True)

            for f in files:
                with open(f, 'r', encoding='utf-8', errors='replace') as fh:
                    html_content = fh.read()
                result = do_convert(html_content)
                name = os.path.splitext(os.path.basename(f))[0] + '.md'
                out_file = os.path.join(output_path, name)
                if os.path.exists(out_file) and not opts['output_overwrite']:
                    sys.stderr.write(f'\nerror: output path "{out_file}" already exists. '
                                   f'Use --output-overwrite to replace existing files\n\n')
                    sys.exit(1)
                with open(out_file, 'w', encoding='utf-8') as fh:
                    fh.write(result)
        else:
            with open(input_path, 'r', encoding='utf-8', errors='replace') as fh:
                html_content = fh.read()
            result = do_convert(html_content)
            write_output(result, output_path)
    else:
        html_content = sys.stdin.read()
        result = do_convert(html_content)
        write_output(result, output_path)


def main():
    opts = parse_cli_args(sys.argv[1:])

    if opts['version']:
        print(VERSION_INFO)
        sys.exit(0)

    if opts['help']:
        print(HELP_TEXT)
        sys.exit(0)

    run(opts)


if __name__ == '__main__':
    main()
