BLOCK_TAGS = frozenset({
    'p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'blockquote', 'pre', 'hr',
    'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',
    'article', 'section', 'header', 'footer', 'nav', 'aside', 'main',
    'figure', 'figcaption', 'details', 'summary',
    'dl', 'dt', 'dd',
    'form', 'fieldset', 'legend',
    'address', 'dialog',
})


def get_code_language(code_node, pre_node=None):
    for cls in code_node.get_classes():
        if cls.startswith('language-'):
            return cls[9:]
        if cls.startswith('lang-'):
            return cls[5:]
    if pre_node:
        for cls in pre_node.get_classes():
            if cls.startswith('language-'):
                return cls[9:]
            if cls.startswith('lang-'):
                return cls[5:]
    return ''


def normalize_ws(text):
    return re.sub(r'[ \t\r\n]+', ' ', text)


class Converter:
    def __init__(self, domain='', options=None):
        self.domain = domain
        options = options or {}
        self.plugin_table = options.get('plugin_table', False)
        self.plugin_strikethrough = options.get('plugin_strikethrough', False)
        self.strong_delimiter = options.get('strong_delimiter', '**')
        self.table_cell_padding = options.get('table_cell_padding', 'aligned')
        self.table_header_promotion = options.get('table_header_promotion', False)
        self.table_newline_behavior = options.get('table_newline_behavior', 'skip')
        self.table_presentation_tables = options.get('table_presentation_tables', False)
        self.table_skip_empty_rows = options.get('table_skip_empty_rows', False)
        self.table_span_cell_behavior = options.get('table_span_cell_behavior', 'empty')

    def convert(self, root):
        result = self._convert_block_children(root)
        # Cleanup
        result = re.sub(r'\n{3,}', '\n\n', result)
        result = result.strip('\n')
        if result:
            result += '\n'
        return result

    def _convert_block_children(self, node):
        """Convert children of a block-level node."""
        parts = []
        for child in node.children:
            part = self._convert_node(child)
            parts.append(part)
        return ''.join(parts)

    def _convert_node(self, node, in_pre=False, in_table_cell=False):
        tag = node.tag

        if tag == '#text':
            text = node.text_content
            if in_pre:
                return text
            if in_table_cell:
                text = normalize_ws(text)
                if not text.strip():
                    return text
                return escape_text_content(text, self.plugin_strikethrough)
            # Normal text node
            text = normalize_ws(text)
            if not text.strip():
                return text  # whitespace-only: return as-is, will be cleaned by block context
            return escape_text_content(text, self.plugin_strikethrough)

        if tag in RAW_TEXT_ELEMENTS:
            return ''

        kw = dict(in_pre=in_pre, in_table_cell=in_table_cell)

        if tag in ('h1','h2','h3','h4','h5','h6'):
            level = int(tag[1])
            inner = self._inline_children(node).strip()
            return f'\n\n{"#"*level} {inner}\n\n'

        if tag == 'p':
            inner = self._inline_children(node).strip()
            if not inner:
                return ''
            inner = apply_line_escaping(inner)
            return f'\n\n{inner}\n\n'

        if tag == 'hr':
            return '\n\n* * *\n\n'

        if tag == 'br':
            if in_table_cell and self.table_newline_behavior == 'preserve':
                return '  <br />'
            return '  \n'

        if tag in ('strong', 'b'):
            inner = self._inline_children(node)
            if not inner.strip():
                return inner
            d = self.strong_delimiter
            return f'{d}{inner}{d}'

        if tag in ('em', 'i'):
            inner = self._inline_children(node)
            if not inner.strip():
                return inner
            return f'*{inner}*'

        if tag in ('code', 'kbd', 'tt', 'var', 'samp'):
            if in_pre:
                return node.text_content_of()
            return self._inline_code(node)

        if tag == 'pre':
            return self._pre(node)

        if tag == 'a':
            href = node.attrs.get('href', '')
            title = node.attrs.get('title', '')
            href = resolve_url(href, self.domain)
            href = encode_markdown_url(href)
            inner = self._inline_children(node)
            if title:
                return f'[{inner}]({href} "{title}")'
            return f'[{inner}]({href})'

        if tag == 'img':
            src = node.attrs.get('src', '')
            alt = node.attrs.get('alt', '')
            title = node.attrs.get('title', '')
            if not src:
                return ''
            src = resolve_url(src, self.domain)
            src = encode_markdown_url(src)
            if title:
                return f'![{alt}]({src} "{title}")'
            return f'![{alt}]({src})'

        if tag == 'blockquote':
            inner = self._convert_block_children(node)
            inner = inner.strip('\n')
            lines = inner.split('\n')
            prefixed = ['> ' + line if line.strip() else '>' for line in lines]
            result = '\n'.join(prefixed)
            return f'\n\n{result}\n\n'

        if tag == 'ul':
            return self._list(node, 'ul')

        if tag == 'ol':
            return self._list(node, 'ol')

        if tag == 'li':
            return self._convert_block_children(node)

        if tag in ('del', 's', 'strike'):
            if self.plugin_strikethrough:
                return f'~~{self._inline_children(node)}~~'
            return self._inline_children(node)

        if tag == 'table':
            if not self.plugin_table:
                return self._block_wrap(node)
            role = node.attrs.get('role', '')
            if role == 'presentation' and not self.table_presentation_tables:
                return self._block_wrap(node)
            return self._render_table(node)

        if tag in ('thead', 'tbody', 'tfoot', 'tr', 'th', 'td'):
            return ''  # handled by _render_table

        if tag == 'dt':
            inner = self._inline_children(node).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag == 'dd':
            inner = self._inline_children(node).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag == 'figcaption':
            inner = self._inline_children(node).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag in BLOCK_TAGS:
            return self._block_wrap(node)

        # Default inline
        return self._inline_children(node)

    def _inline_children(self, node):
        """Convert children, treating them as inline content."""
        parts = []
        for child in node.children:
            parts.append(self._convert_node(child))
        return ''.join(parts)

    def _inline_code(self, node):
        content = node.text_content_of()
        if not content:
            return ''
        max_run = 0
        run = 0
        for c in content:
            if c == '`':
                run += 1
                max_run = max(max_run, run)
            else:
                run = 0
        delim = '`' * (max_run + 1)
        if content.startswith('`') or content.endswith('`'):
            return f'{delim} {content} {delim}'
        return f'{delim}{content}{delim}'

    def _pre(self, node):
        code_node = next((c for c in node.children if c.tag == 'code'), None)
        if code_node:
            lang = get_code_language(code_node, node)
            content = code_node.text_content_of()
        else:
            lang = get_code_language(node)
            content = node.text_content_of()

        if not content.endswith('\n'):
            content += '\n'

        return f'\n\n```{lang}\n{content}```\n\n'

    def _block_wrap(self, node):
        inner = self._convert_block_children(node)
        inner = inner.strip('\n')
        if not inner:
            return ''
        return f'\n\n{inner}\n\n'

    def _list(self, node, list_type):
        """Convert ul or ol list."""
        # Count li items for padding
        li_items = [c for c in node.children if c.tag == 'li']
        n_items = len(li_items)

        if list_type == 'ol':
            # Calculate number width for zero-padding
            if n_items >= 100:
                num_width = 3
            elif n_items >= 10:
                num_width = 2
            else:
                num_width = 1

        items = []
        counter = 1
        for child in node.children:
            if child.tag != 'li':
                continue

            if list_type == 'ul':
                prefix = '- '
            else:
                if num_width > 1:
                    prefix = f'{str(counter).zfill(num_width)}. '
                else:
                    prefix = f'{counter}. '
                counter += 1

            item_str = self._list_item(child, prefix)
            items.append(item_str)

        if not items:
            return ''

        result = '\n'.join(items)
        return f'\n\n{result}\n\n'

    def _list_item(self, node, prefix):
        """Convert a single list item."""
        indent = ' ' * len(prefix)

        # Convert children, getting the raw content
        inner = self._convert_li_content(node)
        inner = inner.strip('\n')

        if not inner:
            return prefix.rstrip()

        if '\n' not in inner:
            # Simple single-line content
            inner = apply_line_escaping(inner)
            return prefix + inner

        # Multi-line content
        lines = inner.split('\n')
        result_lines = []
        first = True
        for line in lines:
            if first:
                escaped = apply_line_escaping(line)
                result_lines.append(prefix + escaped)
                first = False
            else:
                # Indent this line with proper indent
                # For blank lines, use indent (spaces) - this matches original behavior
                if line:
                    result_lines.append(indent + line)
                else:
                    result_lines.append(indent)

        return '\n'.join(result_lines)

    def _convert_li_content(self, node):
        """Convert list item content."""
        parts = []
        for child in node.children:
            if child.tag == '#text':
                text = normalize_ws(child.text_content)
                if text.strip():
                    parts.append(escape_text_content(text, self.plugin_strikethrough))
                elif text and parts:
                    # Whitespace between elements: keep single space
                    parts.append(text)
            elif child.tag in ('ul', 'ol'):
                # Nested list: get its content
                nested = self._list(child, child.tag)
                # Remove the outer \n\n wrapper from nested list
                # The parent list item will handle indentation
                parts.append(nested)
            elif child.tag == 'li':
                parts.append(self._convert_li_content(child))
            elif child.tag == 'p':
                inner = self._inline_children(child).strip()
                if inner:
                    inner = apply_line_escaping(inner)
                    parts.append(f'\n\n{inner}\n\n')
            elif child.tag in BLOCK_TAGS:
                inner = self._convert_block_children(child)
                inner = inner.strip('\n')
                if inner:
                    parts.append(f'\n\n{inner}\n\n')
            else:
                parts.append(self._convert_node(child))

        result = ''.join(parts)
        return result

    def _render_table(self, table_node):
        header_rows, body_rows = self._parse_table(table_node)
        all_rows = header_rows + body_rows

        if not all_rows:
            return ''

        num_cols = max(sum(c.get('colspan', 1) for c in row) for row in all_rows)
        if num_cols == 0:
            return ''

        # Expand colspan
        expanded = []
        for row in all_rows:
            exp = []
            for cell in row:
                content = cell['content']
                colspan = cell.get('colspan', 1)
                exp.append(content)
                for _ in range(colspan - 1):
                    if self.table_span_cell_behavior == 'mirror':
                        exp.append(content)
                    else:
                        exp.append('')
            while len(exp) < num_cols:
                exp.append('')
            expanded.append(exp[:num_cols])

        n_header = len(header_rows)
        if n_header == 0 and self.table_header_promotion and body_rows:
            n_header = 1

        # Skip empty rows
        if self.table_skip_empty_rows:
            new_exp = []
            for i, row in enumerate(expanded):
                if i < n_header or any(c.strip() for c in row):
                    new_exp.append(row)
            expanded = new_exp

        # Add empty header if needed
        if n_header == 0:
            expanded = [[''] * num_cols] + expanded
            n_header = 1

        if not expanded:
            return ''

        # Column widths
        col_widths = [max(len(row[j]) if j < len(row) else 0 for row in expanded)
                      for j in range(num_cols)]
        col_widths = [max(w, 3) for w in col_widths]

        padding = self.table_cell_padding
        lines = []

        for i, row in enumerate(expanded):
            cells = (row + [''] * num_cols)[:num_cols]

            if padding == 'none':
                line = '|' + '|'.join(cells) + '|'
            elif padding == 'aligned':
                formatted = [f' {c:<{col_widths[j]}} ' for j, c in enumerate(cells)]
                line = '|' + '|'.join(formatted) + '|'
            else:  # minimal
                formatted = [f' {c} ' for c in cells]
                line = '|' + '|'.join(formatted) + '|'

            lines.append(line)

            if i == n_header - 1:
                if padding == 'none':
                    sep = '|' + '|'.join(['---'] * num_cols) + '|'
                elif padding == 'aligned':
                    sep = '|' + '|'.join(['-' * (col_widths[j] + 2) for j in range(num_cols)]) + '|'
                else:
                    sep = '|' + '|'.join(['---'] * num_cols) + '|'
                lines.append(sep)

        return '\n\n' + '\n'.join(lines) + '\n\n'

    def _parse_table(self, table_node):
        header_rows = []
        body_rows = []

        def process_tr(tr_node, is_header):
            row = []
            for cell in tr_node.children:
                if cell.tag in ('th', 'td'):
                    colspan = int(cell.attrs.get('colspan', 1))
                    content = self._table_cell_content(cell)
                    row.append({'content': content, 'colspan': colspan})
            if row:
                if is_header:
                    header_rows.append(row)
                else:
                    body_rows.append(row)

        def process_section(sec, is_header):
            for child in sec.children:
                if child.tag == 'tr':
                    process_tr(child, is_header)
                elif child.tag in ('thead', 'tbody', 'tfoot'):
                    process_section(child, child.tag == 'thead')

        for child in table_node.children:
            if child.tag == 'thead':
                process_section(child, True)
            elif child.tag in ('tbody', 'tfoot'):
                process_section(child, False)
            elif child.tag == 'tr':
                has_th = any(c.tag == 'th' for c in child.children)
                process_tr(child, has_th)

        return header_rows, body_rows

    def _table_cell_content(self, cell_node):
        parts = []
        for child in cell_node.children:
            if child.tag == 'br':
                if self.table_newline_behavior == 'preserve':
                    parts.append('  <br />')
                else:
                    parts.append('\n')
            elif child.tag == '#text':
                text = normalize_ws(child.text_content)
                if text.strip():
                    parts.append(escape_text_content(text, self.plugin_strikethrough))
            else:
                parts.append(self._convert_node(child, in_table_cell=True))

        content = ''.join(parts).strip()

        if self.table_newline_behavior == 'skip':
            content = content.replace('\n', ' ')

        return content


def html_to_markdown(html_str, domain='', options=None,
                     include_selectors=None, exclude_selectors=None):
    root = parse_html(html_str)
    root = apply_selectors(root, include_selectors, exclude_selectors)
    converter = Converter(domain=domain, options=options)
    return converter.convert(root)


