#!/usr/bin/env python3
"""
html2markdown - HTML to Markdown converter
Reimplementation of the html-to-markdown CLI tool
"""

import sys
import os
import re
import glob
from html.parser import HTMLParser
import urllib.parse


# ============================================================
# DOM Tree
# ============================================================

class Node:
    __slots__ = ['tag', 'attrs', 'children', 'parent', 'text_content']

    def __init__(self, tag, attrs=None, parent=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        self.parent = parent
        self.text_content = ''

    def append_child(self, child):
        child.parent = self
        self.children.append(child)

    def get_attr(self, name, default=''):
        return self.attrs.get(name, default)

    def get_classes(self):
        return self.attrs.get('class', '').split()

    def text_content_of(self):
        if self.tag == '#text':
            return self.text_content
        return ''.join(c.text_content_of() for c in self.children)

    def __repr__(self):
        if self.tag == '#text':
            return f'Text({repr(self.text_content[:20])})'
        return f'<{self.tag}>'


# ============================================================
# HTML Parser
# ============================================================

VOID_ELEMENTS = frozenset({
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
    'link', 'meta', 'param', 'source', 'track', 'wbr'
})

RAW_TEXT_ELEMENTS = frozenset({'script', 'style', 'head'})


class HTMLDOMParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node('root')
        self.stack = [self.root]
        self._skip_depth = 0

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        attrs_dict = {k.lower(): (v or '') for k, v in attrs}
        node = Node(tag, attrs_dict)
        self.stack[-1].append_child(node)
        if tag in RAW_TEXT_ELEMENTS:
            self._skip_depth += 1
        if tag not in VOID_ELEMENTS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in VOID_ELEMENTS:
            return
        if tag in RAW_TEXT_ELEMENTS:
            self._skip_depth = max(0, self._skip_depth - 1)
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                self.stack = self.stack[:i]
                return

    def handle_data(self, data):
        if self._skip_depth > 0:
            return
        node = Node('#text')
        node.text_content = data
        self.stack[-1].append_child(node)


def parse_html(html_str):
    parser = HTMLDOMParser()
    parser.feed(html_str)
    return parser.root


# ============================================================
# CSS Selector Engine
# ============================================================

def _split_selector_groups(s):
    groups = []
    depth = 0
    current = []
    for c in s:
        if c == '[':
            depth += 1
            current.append(c)
        elif c == ']':
            depth -= 1
            current.append(c)
        elif c == ',' and depth == 0:
            groups.append(''.join(current))
            current = []
        else:
            current.append(c)
    if current:
        groups.append(''.join(current))
    return groups


def _parse_simple_selector(s):
    result = {'tag': None, 'id': None, 'classes': [], 'attrs': []}
    i = 0
    if i < len(s) and s[i] not in '.#[:*':
        j = i
        while j < len(s) and s[j] not in '.#[:':
            j += 1
        tag = s[i:j].lower()
        if tag:
            result['tag'] = tag
        i = j
    elif i < len(s) and s[i] == '*':
        i += 1

    while i < len(s):
        c = s[i]
        if c == '.':
            i += 1
            j = i
            while j < len(s) and s[j] not in '.#[:':
                j += 1
            result['classes'].append(s[i:j])
            i = j
        elif c == '#':
            i += 1
            j = i
            while j < len(s) and s[j] not in '.#[:':
                j += 1
            result['id'] = s[i:j]
            i = j
        elif c == '[':
            i += 1
            j = s.index(']', i)
            attr_str = s[i:j]
            i = j + 1
            for op in ('*=', '~=', '^=', '$=', '|=', '='):
                if op in attr_str:
                    k, v = attr_str.split(op, 1)
                    result['attrs'].append((op, k.strip(), v.strip().strip('"\'').strip("'")))
                    break
            else:
                result['attrs'].append(('exist', attr_str.strip(), ''))
        elif c == ':':
            i += 1
            depth = 0
            while i < len(s):
                if s[i] == '(':
                    depth += 1
                elif s[i] == ')':
                    depth -= 1
                    if depth <= 0:
                        i += 1
                        break
                elif depth == 0 and s[i] in '.#[:':
                    break
                i += 1
        else:
            i += 1
    return result


def _tokenize_selector(s):
    tokens = []
    i = 0
    s = s.strip()
    pending_combinator = None

    while i < len(s):
        if s[i] == ' ':
            i += 1
            while i < len(s) and s[i] == ' ':
                i += 1
            if i < len(s) and s[i] not in '>+~':
                pending_combinator = ' '
            continue

        if s[i] in '>+~':
            pending_combinator = s[i]
            i += 1
            while i < len(s) and s[i] == ' ':
                i += 1
            continue

        j = i
        depth = 0
        while j < len(s):
            if s[j] == '[':
                depth += 1
            elif s[j] == ']':
                depth -= 1
            elif depth == 0 and s[j] in ' >+~':
                break
            j += 1

        simple = _parse_simple_selector(s[i:j])
        combinator = pending_combinator
        tokens.append((combinator, simple))
        pending_combinator = None
        i = j

    return tokens


def _match_simple(node, sel):
    if node.tag == '#text':
        return False
    if sel['tag'] and node.tag != sel['tag']:
        return False
    if sel['id'] is not None:
        if node.attrs.get('id', '') != sel['id']:
            return False
    node_classes = node.get_classes()
    for cls in sel['classes']:
        if cls not in node_classes:
            return False
    for op, attr, val in sel['attrs']:
        node_val = node.attrs.get(attr)
        if op == 'exist':
            if node_val is None:
                return False
        elif node_val is None:
            return False
        elif op == '=':
            if node_val != val:
                return False
        elif op == '*=':
            if val not in node_val:
                return False
        elif op == '^=':
            if not node_val.startswith(val):
                return False
        elif op == '$=':
            if not node_val.endswith(val):
                return False
        elif op == '~=':
            if val not in node_val.split():
                return False
        elif op == '|=':
            if node_val != val and not node_val.startswith(val + '-'):
                return False
    return True


def _match_parts(node, parts):
    if not parts:
        return False

    combinator, simple = parts[-1]
    if not _match_simple(node, simple):
        return False

    if len(parts) == 1:
        return True

    rest = parts[:-1]

    if combinator == ' ' or combinator is None:
        if len(parts) > 1:
            ancestor = node.parent
            while ancestor and ancestor.tag != 'root':
                if _match_parts(ancestor, rest):
                    return True
                ancestor = ancestor.parent
            return False
        return True
    elif combinator == '>':
        return node.parent and _match_parts(node.parent, rest)
    elif combinator == '+':
        if node.parent:
            siblings = [c for c in node.parent.children if c.tag != '#text']
            idx = next((i for i, c in enumerate(siblings) if c is node), -1)
            if idx > 0:
                return _match_parts(siblings[idx - 1], rest)
        return False
    elif combinator == '~':
        if node.parent:
            siblings = [c for c in node.parent.children if c.tag != '#text']
            idx = next((i for i, c in enumerate(siblings) if c is node), -1)
            for i in range(idx):
                if _match_parts(siblings[i], rest):
                    return True
        return False

    return False


def matches_selector(node, selector_str):
    if node.tag == '#text':
        return False
    groups = _split_selector_groups(selector_str)
    for group in groups:
        parts = _tokenize_selector(group.strip())
        if parts and _match_parts(node, parts):
            return True
    return False


def find_matching_nodes(root, selector_str):
    results = []
    def traverse(node):
        if node.tag not in ('#text', 'root'):
            if matches_selector(node, selector_str):
                results.append(node)
        for child in node.children:
            traverse(child)
    traverse(root)
    return results


def apply_selectors(root, include_selectors=None, exclude_selectors=None):
    if include_selectors:
        matched = []
        for sel in include_selectors:
            matched.extend(find_matching_nodes(root, sel))
        new_root = Node('root')
        for node in matched:
            new_root.append_child(node)
        return new_root

    if exclude_selectors:
        excluded = set()
        for sel in exclude_selectors:
            for node in find_matching_nodes(root, sel):
                excluded.add(id(node))

        def remove_excluded(node):
            node.children = [c for c in node.children if id(c) not in excluded]
            for child in node.children:
                remove_excluded(child)

        remove_excluded(root)

    return root


# ============================================================
# URL Handling
# ============================================================

def encode_markdown_url(url):
    if not url:
        return url
    result = []
    for c in url:
        if c == '(':
            result.append('%28')
        elif c == ')':
            result.append('%29')
        elif c == '[':
            result.append('%5B')
        elif c == ']':
            result.append('%5D')
        elif c == ' ':
            result.append('%20')
        elif c == '\\':
            result.append('%5C')
        else:
            result.append(c)
    return ''.join(result)


def resolve_url(url, domain):
    if not url or not domain:
        return url
    if re.match(r'^[a-zA-Z][a-zA-Z0-9+\-.]*:', url):
        return url
    if url.startswith('//'):
        return url
    if '://' not in domain:
        domain = 'https://' + domain
    parsed_base = urllib.parse.urlparse(domain)
    base_scheme = parsed_base.scheme
    base_netloc = parsed_base.netloc
    if url.startswith('/'):
        return f"{base_scheme}://{base_netloc}{url}"
    else:
        return f"{base_scheme}://{base_netloc}/{url}"


# ============================================================
# Text Escaping
# ============================================================

def escape_text_content(text, strikethrough_plugin=False):
    """Smart escape text content from HTML for markdown output."""
    if not text:
        return text

    # Step 1: Escape backslashes (must be first)
    text = text.replace('\\', '\\\\')

    # Step 2: HTML entities for < >
    text = text.replace('<', '&lt;').replace('>', '&gt;')

    # Step 3: Escape [ when followed by ]
    text = _escape_brackets(text)

    # Step 4: Escape * when followed by non-whitespace
    text = _escape_left_flanking(text, '*')

    # Step 5: Escape _ when followed by non-whitespace
    text = _escape_left_flanking(text, '_')

    # Step 6: Escape ~ when followed by non-whitespace (strikethrough plugin only)
    if strikethrough_plugin:
        text = _escape_left_flanking(text, '~')

    # Step 7: Escape backticks
    text = text.replace('`', '\\`')

    return text


def _escape_brackets(text):
    """Escape [ when there's a ] after it."""
    if '[' not in text or ']' not in text:
        return text
    result = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == '[' and ']' in text[i+1:]:
            result.append('\\[')
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def _escape_left_flanking(text, char):
    """Escape char when followed by non-whitespace."""
    if char not in text:
        return text
    result = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == char:
            next_c = text[i+1] if i+1 < len(text) else ''
            if next_c and next_c not in ' \t\n\r':
                result.append('\\' + char)
            else:
                result.append(char)
        else:
            result.append(c)
        i += 1
    return ''.join(result)


def apply_line_escaping(text):
    """Apply line-start escaping."""
    lines = text.split('\n')
    return '\n'.join(_escape_line(line) for line in lines)


def _escape_line(line):
    """Escape line-start markdown syntax."""
    if not line:
        return line

    # ATX heading: #+ followed by space
    if re.match(r'^#{1,6} ', line):
        return '\\' + line

    # Unordered list: - + * followed by space or alone
    if re.match(r'^[-+*][ ]', line) or re.match(r'^[-+*]$', line):
        return '\\' + line

    # Ordered list: digits followed by . or ) with space or alone
    m = re.match(r'^(\d+)([.)])([ ]|$)', line)
    if m:
        pos = m.start(2)
        return line[:pos] + '\\' + line[pos:]

    # Lines of only dashes (3+): horizontal rule
    if re.match(r'^-{3,}$', line):
        return '\\' + line

    # Single dash alone: setext h2 prevention
    if line == '-':
        return '\\' + line

    # Fenced code block at start: 3+ backticks
    if re.match(r'^`{3,}', line):
        return '\\' + line[0] + line[1:]

    return line


# ============================================================
# Markdown Generator
# ============================================================

BLOCK_TAGS = frozenset({
    'p', 'div', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'ul', 'ol', 'li', 'blockquote', 'pre', 'hr',
    'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',
    'article', 'section', 'header', 'footer', 'nav', 'aside', 'main',
    'figure', 'figcaption', 'details', 'summary',
    'dl', 'dt', 'dd',
    'form', 'fieldset', 'legend',
    'address', 'dialog',
})


def get_code_language(code_node, pre_node=None):
    for cls in code_node.get_classes():
        if cls.startswith('language-'):
            return cls[9:]
        if cls.startswith('lang-'):
            return cls[5:]
    if pre_node:
        for cls in pre_node.get_classes():
            if cls.startswith('language-'):
                return cls[9:]
            if cls.startswith('lang-'):
                return cls[5:]
    return ''


def normalize_ws(text):
    return re.sub(r'[ \t\r\n]+', ' ', text)


class Converter:
    def __init__(self, domain='', options=None):
        self.domain = domain
        options = options or {}
        self.plugin_table = options.get('plugin_table', False)
        self.plugin_strikethrough = options.get('plugin_strikethrough', False)
        self.strong_delimiter = options.get('strong_delimiter', '**')
        self.table_cell_padding = options.get('table_cell_padding', 'aligned')
        self.table_header_promotion = options.get('table_header_promotion', False)
        self.table_newline_behavior = options.get('table_newline_behavior', 'skip')
        self.table_presentation_tables = options.get('table_presentation_tables', False)
        self.table_skip_empty_rows = options.get('table_skip_empty_rows', False)
        self.table_span_cell_behavior = options.get('table_span_cell_behavior', 'empty')

    def convert(self, root):
        result = self._convert_block_children(root)
        # Cleanup
        result = re.sub(r'\n{3,}', '\n\n', result)
        result = result.strip('\n')
        if result:
            result += '\n'
        return result

    def _convert_block_children(self, node):
        """Convert children of a block-level node."""
        parts = []
        for child in node.children:
            part = self._convert_node(child)
            parts.append(part)
        return ''.join(parts)

    def _convert_node(self, node, in_pre=False, in_table_cell=False):
        tag = node.tag

        if tag == '#text':
            text = node.text_content
            if in_pre:
                return text
            if in_table_cell:
                text = normalize_ws(text)
                if not text.strip():
                    return text
                return escape_text_content(text, self.plugin_strikethrough)
            # Normal text node
            text = normalize_ws(text)
            if not text.strip():
                return text  # whitespace-only: return as-is, will be cleaned by block context
            return escape_text_content(text, self.plugin_strikethrough)

        if tag in RAW_TEXT_ELEMENTS:
            return ''

        kw = dict(in_pre=in_pre, in_table_cell=in_table_cell)

        if tag in ('h1','h2','h3','h4','h5','h6'):
            level = int(tag[1])
            inner = self._inline_children(node).strip()
            return f'\n\n{"#"*level} {inner}\n\n'

        if tag == 'p':
            inner = self._inline_children(node).strip()
            if not inner:
                return ''
            inner = apply_line_escaping(inner)
            return f'\n\n{inner}\n\n'

        if tag == 'hr':
            return '\n\n* * *\n\n'

        if tag == 'br':
            if in_table_cell and self.table_newline_behavior == 'preserve':
                return '  <br />'
            return '  \n'

        if tag in ('strong', 'b'):
            inner = self._inline_children(node)
            if not inner.strip():
                return inner
            d = self.strong_delimiter
            return f'{d}{inner}{d}'

        if tag in ('em', 'i'):
            inner = self._inline_children(node)
            if not inner.strip():
                return inner
            return f'*{inner}*'

        if tag in ('code', 'kbd', 'tt', 'var', 'samp'):
            if in_pre:
                return node.text_content_of()
            return self._inline_code(node)

        if tag == 'pre':
            return self._pre(node)

        if tag == 'a':
            href = node.attrs.get('href', '')
            title = node.attrs.get('title', '')
            href = resolve_url(href, self.domain)
            href = encode_markdown_url(href)
            inner = self._inline_children(node)
            if title:
                return f'[{inner}]({href} "{title}")'
            return f'[{inner}]({href})'

        if tag == 'img':
            src = node.attrs.get('src', '')
            alt = node.attrs.get('alt', '')
            title = node.attrs.get('title', '')
            if not src:
                return ''
            src = resolve_url(src, self.domain)
            src = encode_markdown_url(src)
            if title:
                return f'![{alt}]({src} "{title}")'
            return f'![{alt}]({src})'

        if tag == 'blockquote':
            inner = self._convert_block_children(node)
            inner = inner.strip('\n')
            lines = inner.split('\n')
            prefixed = ['> ' + line if line.strip() else '>' for line in lines]
            result = '\n'.join(prefixed)
            return f'\n\n{result}\n\n'

        if tag == 'ul':
            return self._list(node, 'ul')

        if tag == 'ol':
            return self._list(node, 'ol')

        if tag == 'li':
            return self._convert_block_children(node)

        if tag in ('del', 's', 'strike'):
            if self.plugin_strikethrough:
                return f'~~{self._inline_children(node)}~~'
            return self._inline_children(node)

        if tag == 'table':
            if not self.plugin_table:
                return self._block_wrap(node)
            role = node.attrs.get('role', '')
            if role == 'presentation' and not self.table_presentation_tables:
                return self._block_wrap(node)
            return self._render_table(node)

        if tag in ('thead', 'tbody', 'tfoot', 'tr', 'th', 'td'):
            return ''  # handled by _render_table

        if tag == 'dt':
            inner = self._inline_children(node).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag == 'dd':
            inner = self._inline_children(node).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag == 'figcaption':
            inner = self._inline_children(node).strip()
            return f'\n\n{inner}\n\n' if inner else ''

        if tag in BLOCK_TAGS:
            return self._block_wrap(node)

        # Default inline
        return self._inline_children(node)

    def _inline_children(self, node):
        """Convert children, treating them as inline content."""
        parts = []
        for child in node.children:
            parts.append(self._convert_node(child))
        return ''.join(parts)

    def _inline_code(self, node):
        content = node.text_content_of()
        if not content:
            return ''
        max_run = 0
        run = 0
        for c in content:
            if c == '`':
                run += 1
                max_run = max(max_run, run)
            else:
                run = 0
        delim = '`' * (max_run + 1)
        if content.startswith('`') or content.endswith('`'):
            return f'{delim} {content} {delim}'
        return f'{delim}{content}{delim}'

    def _pre(self, node):
        code_node = next((c for c in node.children if c.tag == 'code'), None)
        if code_node:
            lang = get_code_language(code_node, node)
            content = code_node.text_content_of()
        else:
            lang = get_code_language(node)
            content = node.text_content_of()

        if not content.endswith('\n'):
            content += '\n'

        return f'\n\n```{lang}\n{content}```\n\n'

    def _block_wrap(self, node):
        inner = self._convert_block_children(node)
        inner = inner.strip('\n')
        if not inner:
            return ''
        return f'\n\n{inner}\n\n'

    def _list(self, node, list_type):
        """Convert ul or ol list."""
        # Count li items for padding
        li_items = [c for c in node.children if c.tag == 'li']
        n_items = len(li_items)

        if list_type == 'ol':
            # Calculate number width for zero-padding
            if n_items >= 100:
                num_width = 3
            elif n_items >= 10:
                num_width = 2
            else:
                num_width = 1

        items = []
        counter = 1
        for child in node.children:
            if child.tag != 'li':
                continue

            if list_type == 'ul':
                prefix = '- '
            else:
                if num_width > 1:
                    prefix = f'{str(counter).zfill(num_width)}. '
                else:
                    prefix = f'{counter}. '
                counter += 1

            item_str = self._list_item(child, prefix)
            items.append(item_str)

        if not items:
            return ''

        result = '\n'.join(items)
        return f'\n\n{result}\n\n'

    def _list_item(self, node, prefix):
        """Convert a single list item."""
        indent = ' ' * len(prefix)

        # Convert children, getting the raw content
        inner = self._convert_li_content(node)
        inner = inner.strip('\n')

        if not inner:
            return prefix.rstrip()

        if '\n' not in inner:
            # Simple single-line content
            inner = apply_line_escaping(inner)
            return prefix + inner

        # Multi-line content
        lines = inner.split('\n')
        result_lines = []
        first = True
        for line in lines:
            if first:
                escaped = apply_line_escaping(line)
                result_lines.append(prefix + escaped)
                first = False
            else:
                # Indent this line with proper indent
                # For blank lines, use indent (spaces) - this matches original behavior
                if line:
                    result_lines.append(indent + line)
                else:
                    result_lines.append(indent)

        return '\n'.join(result_lines)

    def _convert_li_content(self, node):
        """Convert list item content."""
        parts = []
        for child in node.children:
            if child.tag == '#text':
                text = normalize_ws(child.text_content)
                if text.strip():
                    parts.append(escape_text_content(text, self.plugin_strikethrough))
                elif text and parts:
                    # Whitespace between elements: keep single space
                    parts.append(text)
            elif child.tag in ('ul', 'ol'):
                # Nested list: get its content
                nested = self._list(child, child.tag)
                # Remove the outer \n\n wrapper from nested list
                # The parent list item will handle indentation
                parts.append(nested)
            elif child.tag == 'li':
                parts.append(self._convert_li_content(child))
            elif child.tag == 'p':
                inner = self._inline_children(child).strip()
                if inner:
                    inner = apply_line_escaping(inner)
                    parts.append(f'\n\n{inner}\n\n')
            elif child.tag in BLOCK_TAGS:
                inner = self._convert_block_children(child)
                inner = inner.strip('\n')
                if inner:
                    parts.append(f'\n\n{inner}\n\n')
            else:
                parts.append(self._convert_node(child))

        result = ''.join(parts)
        return result

    def _render_table(self, table_node):
        header_rows, body_rows = self._parse_table(table_node)
        all_rows = header_rows + body_rows

        if not all_rows:
            return ''

        num_cols = max(sum(c.get('colspan', 1) for c in row) for row in all_rows)
        if num_cols == 0:
            return ''

        # Expand colspan
        expanded = []
        for row in all_rows:
            exp = []
            for cell in row:
                content = cell['content']
                colspan = cell.get('colspan', 1)
                exp.append(content)
                for _ in range(colspan - 1):
                    if self.table_span_cell_behavior == 'mirror':
                        exp.append(content)
                    else:
                        exp.append('')
            while len(exp) < num_cols:
                exp.append('')
            expanded.append(exp[:num_cols])

        n_header = len(header_rows)
        if n_header == 0 and self.table_header_promotion and body_rows:
            n_header = 1

        # Skip empty rows
        if self.table_skip_empty_rows:
            new_exp = []
            for i, row in enumerate(expanded):
                if i < n_header or any(c.strip() for c in row):
                    new_exp.append(row)
            expanded = new_exp

        # Add empty header if needed
        if n_header == 0:
            expanded = [[''] * num_cols] + expanded
            n_header = 1

        if not expanded:
            return ''

        # Column widths
        col_widths = [max(len(row[j]) if j < len(row) else 0 for row in expanded)
                      for j in range(num_cols)]
        col_widths = [max(w, 3) for w in col_widths]

        padding = self.table_cell_padding
        lines = []

        for i, row in enumerate(expanded):
            cells = (row + [''] * num_cols)[:num_cols]

            if padding == 'none':
                line = '|' + '|'.join(cells) + '|'
            elif padding == 'aligned':
                formatted = [f' {c:<{col_widths[j]}} ' for j, c in enumerate(cells)]
                line = '|' + '|'.join(formatted) + '|'
            else:  # minimal
                formatted = [f' {c} ' for c in cells]
                line = '|' + '|'.join(formatted) + '|'

            lines.append(line)

            if i == n_header - 1:
                if padding == 'none':
                    sep = '|' + '|'.join(['---'] * num_cols) + '|'
                elif padding == 'aligned':
                    sep = '|' + '|'.join(['-' * (col_widths[j] + 2) for j in range(num_cols)]) + '|'
                else:
                    sep = '|' + '|'.join(['---'] * num_cols) + '|'
                lines.append(sep)

        return '\n\n' + '\n'.join(lines) + '\n\n'

    def _parse_table(self, table_node):
        header_rows = []
        body_rows = []

        def process_tr(tr_node, is_header):
            row = []
            for cell in tr_node.children:
                if cell.tag in ('th', 'td'):
                    colspan = int(cell.attrs.get('colspan', 1))
                    content = self._table_cell_content(cell)
                    row.append({'content': content, 'colspan': colspan})
            if row:
                if is_header:
                    header_rows.append(row)
                else:
                    body_rows.append(row)

        def process_section(sec, is_header):
            for child in sec.children:
                if child.tag == 'tr':
                    process_tr(child, is_header)
                elif child.tag in ('thead', 'tbody', 'tfoot'):
                    process_section(child, child.tag == 'thead')

        for child in table_node.children:
            if child.tag == 'thead':
                process_section(child, True)
            elif child.tag in ('tbody', 'tfoot'):
                process_section(child, False)
            elif child.tag == 'tr':
                has_th = any(c.tag == 'th' for c in child.children)
                process_tr(child, has_th)

        return header_rows, body_rows

    def _table_cell_content(self, cell_node):
        parts = []
        for child in cell_node.children:
            if child.tag == 'br':
                if self.table_newline_behavior == 'preserve':
                    parts.append('  <br />')
                else:
                    parts.append('\n')
            elif child.tag == '#text':
                text = normalize_ws(child.text_content)
                if text.strip():
                    parts.append(escape_text_content(text, self.plugin_strikethrough))
            else:
                parts.append(self._convert_node(child, in_table_cell=True))

        content = ''.join(parts).strip()

        if self.table_newline_behavior == 'skip':
            content = content.replace('\n', ' ')

        return content


def html_to_markdown(html_str, domain='', options=None,
                     include_selectors=None, exclude_selectors=None):
    root = parse_html(html_str)
    root = apply_selectors(root, include_selectors, exclude_selectors)
    converter = Converter(domain=domain, options=options)
    return converter.convert(root)


