# This confirms: default 'skip' means skip tables with newlines

# Now let me fix _table_cell_content and _render_table:
# 1. _table_cell_content should always generate content with '\n' for <br>
# 2. In _render_table, check if any cell has '\n' when skip mode
# 3. When rendering cells (non-skip or no newlines):
#    - For preserve mode: replace '\n' with '  <br />'
#    - For skip/default mode: just keep '\n' -> won't be rendered as table if skip

python3 << 'PYEOF'
with open('/workspace/html2markdown.py', 'r') as f:
    content = f.read()

# Fix _table_cell_content to always use '\n' for <br>
old_cell_content = """    def _table_cell_content(self, cell_node):
        parts = []
        for child in cell_node.children:
            if child.tag == 'br':
                if self.table_newline_behavior == 'preserve':
                    parts.append('  <br />')
                else:
                    parts.append('\\n')
            elif child.tag == '#text':
                text = normalize_ws(child.text_content)
                if text.strip():
                    parts.append(escape_text_content(text, self.plugin_strikethrough))
            else:
                parts.append(self._convert_node(child, in_table_cell=True))

        content = ''.join(parts).strip()

        if self.table_newline_behavior == 'skip':
            content = content.replace('\\n', ' ')

        return content"""

new_cell_content = """    def _table_cell_content(self, cell_node):
        parts = []
        has_newline = False
        for child in cell_node.children:
            if child.tag == 'br':
                # Always record as \\n internally; transform at render time
                parts.append('\\n')
                has_newline = True
            elif child.tag == '#text':
                text = normalize_ws(child.text_content)
                if text.strip():
                    parts.append(escape_text_content(text, self.plugin_strikethrough))
            else:
                parts.append(self._convert_node(child, in_table_cell=True))

        content = ''.join(parts).strip()
        return content"""

if old_cell_content in content:
    content = content.replace(old_cell_content, new_cell_content)
    print("Fix _table_cell_content applied")
else:
    print("Pattern not found for _table_cell_content!")
    idx = content.find("def _table_cell_content")
    print(repr(content[idx:idx+400]))

# Fix _render_table to check newlines and handle preserve/skip modes
# Need to update the part that renders cells
old_render_skip_check = """        # Check 'skip' behavior: if any cell has newlines, render as plain content
        if self.table_newline_behavior == 'skip':
            for row in all_rows:
                for cell in row:
                    if '\\n' in cell.get('content', ''):
                        return self._block_wrap(table_node)"""

new_render_skip_check = """        # Check 'skip' behavior: if any cell has newlines, render as plain content
        has_newlines = any('\\n' in cell.get('content', '') for row in all_rows for cell in row)
        if self.table_newline_behavior == 'skip' and has_newlines:
            return self._block_wrap(table_node)

        # For 'preserve' mode, transform \\n to <br /> in cell content
        if self.table_newline_behavior == 'preserve' and has_newlines:
            for row in all_rows:
                for cell in row:
                    cell['content'] = cell['content'].replace('\\n', '  <br />')"""

if old_render_skip_check in content:
    content = content.replace(old_render_skip_check, new_render_skip_check)
    print("Fix _render_table skip check applied")
else:
    print("Pattern not found for skip check!")

with open('/workspace/html2markdown.py', 'w') as f:
    f.write(content)
PYEOF

